            vector<int> T(L, -1); T.back() = p;
            for (int i = 2; i <= q + 1; ++i) T.end()[-i] = 9;
            int flg = 1;
            for (int i = 0, x = 0, y = o; i < S.size() && flg; ++i, --y) {
                if (!y) ++x, y = L + (p + x >= 10 && q + 1 == L);
