const int N=2e5+5,M=N*40;
int q,n,tag[M],t[M],ls[M],rs[M],cnt,rt;
map<pair<int,int>,int>mp;
void change(int &x,int l,int r,int L,int R,int w){
	if(!x)x=++cnt;
	if(l>=L&&r<=R){
		tag[x]+=w;
		t[x]=tag[x]?r-l+1:t[ls[x]]+t[rs[x]];
		return;
	}int mid=(l+r)>>1;
	if(mid>=L)change(ls[x],l,mid,L,R,w);
	if(mid+1<=R)change(rs[x],mid+1,r,L,R,w);
	if(tag[x])t[x]=r-l+1;
	else t[x]=t[ls[x]]+t[rs[x]];
}
