  for (int i = n; i--; )
  for (int j = n; j--; ) if (auto [x, _, y] = segs[i]; 1) if (auto [X, l, r] = segs[j]; x != X) {
    if (y < 0) y = -y, tie(l, r) = pair{-r, -l};
    if (X < x) swap(l, r);
    auto ll = x - 1. * (X - x) * y / (l - y), rr = x - 1. * (X - x) * y / (r - y);
    if (ll > rr) scov += !cov[i]++;
    if (rr < 0) ev.push_back({rr, i}); else scov += !cov[i]++;
    if (ll < 0) ev.push_back({ll, ~i}); else scov -= !--cov[i];
  }
  sort((pair<uint64_t, int>*)&ev[0], (pair<uint64_t, int>*)&*ev.end());
  double ans{}, p{};
  for (auto& [x, i]: ev) {
    if (scov == n - 1) ans -= x - p;
    scov += i < 0? -!--cov[~i]: !cov[i]++;
    p = x;
  }
