mt19937_64 rnd(time(0));
const int MAXN=1e5+5;
int n,m,k,N;ll p,g;
ll a[MAXN];
ll ksm(LL a,ll b,ll MOD){LL r=1;while(b){if(b&1)r=r*a%MOD;a=a*a%MOD,b>>=1;}return r;}
bool is_prime(ll x){
	for(ll i=2;i*i<=x;i++) if(x%i==0) return false;
	return true;
}
void get_g(){
	vector<ll> pr;
	for(ll i=1;i*i<=p-1;i++) if((p-1)%i==0){
		pr.push_back(i);
		if(i!=1) pr.push_back((p-1)/i);
	}
	while(1){
		ll x=rnd()%(p-1)+1;
		bool flag=true;
		for(ll r:pr) if(ksm(x,r,p)==1) flag=false;
		if(flag) {g=x;return;}
	}
}
int main(){
	ios::sync_with_stdio(false);
	// freopen("Otomachi_Una.in","r",stdin);
	// freopen("Otomachi_Una.out","w",stdout);
	cin>>n>>m>>k;N=n*2/(n%2==0?2:1);
	ll L=(ll)(1e14)/N;
	while(1){
		p=(rnd()%L+1)*N+1;
		if(is_prime(p)) break;
	}
	get_g();
