def simplify( t ):
	[ n, m ] = t
	if m < 0:
		[ n, m ] = [ -n, -m ]
	if m == 0:
		[ n, m ] = [ 1, 0 ]
	return [ n, m ]

def do( S ):
	[ n, m ] = [ 0, 1 ]
	for c in S:
		if c == 'R':
			[ n, m ] = simplify( [ n + m, m ] )
		if c == 'S':
			[ n, m ] = simplify( [ -m, n ] )
	return [ n, m ]

def undo( t ):
	[ n, m ] = t
	S = ""
	while [ n, m ] != [ 0, 1 ]:
		if n < 0:
			[ n, m ] = simplify( [ n + m, m ] )
			S += "R"
		else:
			[ n, m ] = simplify( [ -m, n ] )
			S += "S"
	return S

