	T1::splay(u);
	int rnk[2]={T1::siz[T1::ch[u][0]][0],T1::siz[T1::ch[u][0]][1]};
	int tmp=rnk[0]?T2::kth(T1::rt[u][0],rnk[0]):0;
	if(tmp) T2::splay(tmp),ret+=T2::sum[T2::ch[tmp][1]];
	else ret+=T2::sum[T1::rt[u][0]];
	tmp=rnk[1]?T2::kth(T1::rt[u][1],rnk[1]):0;
	if(tmp) T2::splay(tmp),ret+=T2::sum[T2::ch[tmp][1]];
	else ret+=T2::sum[T1::rt[u][1]];
	return ret;
}

int access(int x){
