const int MOD=998244353;
int m;
struct Mat {
	unsigned long long f[11][11];
	Mat() { memset(f,0,sizeof(f)); }
	friend Mat operator*(const Mat&u,const Mat&v) {
		Mat w;
		for(int i=0;i<=m;++i) for(int k=i;k<=m;++k) if(u.f[i][k]) for(int j=k;j<=m;++j) {
			if(v.f[k][j]) w.f[i][j]+=u.f[i][k]*v.f[k][j];
		}
		for(int i=0;i<=m;++i) for(int j=i;j<=m;++j) w.f[i][j]%=MOD;
		return w;
	}
}	I;
Mat ksm(Mat a,int b) { Mat s=I; for(;b;a=a*a,b>>=1) if(b&1) s=s*a; return s; }
struct Segt {
	int N; Mat f[1<<18|5];
	void init(int d) { N=2<<__lg(d),fill(f,f+(N<<1),I); }
	void upd(int x,Mat&o) { for(f[x+=N]=o,x>>=1;x;x>>=1) f[x]=f[x<<1]*f[x<<1|1]; }
}	T;
struct info { int l,r; Mat w; };
bool operator<(const info&a,const info&b) { return a.l<b.l; }
void solve(int n,int k,vector<info>&a) {
	if(n<=1000) {
		vector<int>b(n);
		for(int i=0;i<(int)a.size();++i) for(int j=a[i].l;j<=a[i].r;++j) b[j]=i;
		Mat o=I;
		for(int i=0;i<n;++i) o=o*a[b[1ll*i*k%n]].w;
		return cout<<o.f[0][m]<<"\n",void();
	}
	if(2*k>n) {
		if(a[0].r>0) a[0].l=1,a.insert(a.begin(),{0,0,a[0].w});
		reverse(a.begin()+1,a.end()),k=n-k;
		for(auto i=1;i<(int)a.size();++i) swap(a[i].l,a[i].r),a[i].l=n-a[i].l,a[i].r=n-a[i].r;
	}
	T.init(a.size());
	vector<info>c,b;
	for(int i=0;i<(int)a.size();++i) {
		int l=a[i].l%k,r=a[i].r%k;
		Mat x=ksm(a[i].w,(a[i].r-a[i].l)/k),y=x*a[i].w;
		if(l<=r) T.upd(i,x),c.push_back({l,i,y}),c.push_back({r+1,i,x});
		else if(l==r+1) T.upd(i,y);
		else T.upd(i,y),c.push_back({r+1,i,x}),c.push_back({l,i,y});
	}
	sort(c.begin(),c.end()),c.push_back({k,-1,I});
	if(0<c[0].l) b.push_back({0,c[0].l-1,T.f[1]});
	for(int i=0;c[i].l<k;++i) {
		T.upd(c[i].r,c[i].w);
		if(c[i].l<c[i+1].l) b.push_back({c[i].l,c[i+1].l-1,T.f[1]});
	}
	solve(k,k-n%k,b);
}
