        for(int i=1;i<=cnt[op];++i){
            auto [u,v]=e[op][i];
            if(fl[u]||fl[v])continue;
            d[op][u].push_back(i);
            d[op][v].push_back(i);
        }
    }
    int no=0;
    for(int i=1;i<=n;++i){
        if(fl[i])continue;
        if(d[0][i].size()+d[1][i].size()<=3){
            no=i;
            break;
        }
    }
    if(d[0][no].size()+d[1][no].size()==2){
        fl[no]=1;
        --cn;
        solve();
        ve.push_back({d[0][no][0],d[1][no][0]});
