vector<pii> stos;

int okskippra(int a, int b)
{
	for (int i=a; i<=b; i++)
		if (!zprawej[i].empty())
			return 0;
	return 1;
}

int okskiplew(int a, int b)
{
	for (int i=a; i<=b; i++)
		if (!zlewej[i].empty())
			return 0;
	return 1;
}

void dodaj(vector<pii> &wek)
{
	for (int i=1; i<(int)wek.size(); i++)
	{
		stos.push_back(wek[i]);
		bylo[wek[i].first][wek[i].second]=1;
	}
}

void dodajodw(vector<pii> &wek)
{
	for (int i=(int)wek.size()-2; i>=0; i--)
	{
		stos.push_back(wek[i]);
		bylo[wek[i].first][wek[i].second]=1;
	}
}

void dodajjeden(pii v)
{
	bylo[v.first][v.second]=1;
	stos.push_back(v);
}

void rollback(int rs)
{
	while((int)stos.size()>rs)
	{
		bylo[stos.back().first][stos.back().second]=0;
		stos.pop_back();
	}
}

int bylem(pii v)
{
	return bylo[v.first][v.second];
}

void rekpra(int a, int b, int rs);

void reklew(int a, int b, int rs)
{
	if (a==(int)lewy.size())
	{
		if (okskippra(b+1, (int)prawy.size()-1))
		{
			wyn=stos;
			ans(1);
		}
		return;
	}
	if (bylem(lewy[a]))
		return;
	dodajjeden(lewy[a]);
	rs++;
	debug() << "lew " << imie(a) << imie(b) << imie(stos);
	if (!zlewej[a].empty())
	{
		pii gdz=zlewej[a][0].first;
		int num=zlewej[a][0].second;
		if (!gdz.first)
		{
			if (!okskiplew(a+1, gdz.second-1) || gdz.second<=a)
				return;
			dodaj(bomble[num]);
			reklew(gdz.second+1, b, stos.size());
		}
		else
		{
			if (!okskippra(b+1, gdz.second-1) || gdz.second<=b)
				return;
			dodaj(bomble[num]);
			rekpra(a, gdz.second+1, stos.size());
		}
		return;
	}
	
	reklew(a+1, b, rs);
	rollback(rs);
	
	if (probuj_lewo_prawo(lewy[a]))
	{
		int x=numpra[glo.back().first][glo.back().second];
		if (okskippra(b+1, x) || x<=b)
		{
			dodaj(glo);
			rekpra(a, x+1, stos.size());
		}
	}
}

void rekpra(int a, int b, int rs)
{
	if (b==(int)prawy.size())
	{
		if (okskiplew(a+1, (int)lewy.size()-1))
		{
			wyn=stos;
			ans(1);
		}
		return;
	}
	if (bylem(prawy[b]))
		return;
	dodajjeden(prawy[b]);
	rs++;
	debug() << "pra " << imie(a) << imie(b) << imie(stos);
	if (!zprawej[b].empty())
	{
		pii gdz=zprawej[b][0].first;
		int num=zprawej[b][0].second;
		if (!gdz.first)
		{
			if (!okskiplew(a+1, gdz.second-1) || gdz.second<=a)
				return;
			dodajodw(bomble[num]);
			reklew(gdz.second+1, b, stos.size());
		}
		else
		{
			if (!okskippra(b+1, gdz.second-1) || gdz.second<=b)
				return;
			dodaj(bomble[num]);
			rekpra(a, gdz.second+1, stos.size());
		}
		return;
	}
	
	rekpra(a, b+1, rs);
	rollback(rs);
	
	if (probuj_prawo_lewo(prawy[b]))
	{
		int x=numlew[glo.back().first][glo.back().second];
		if (okskiplew(a+1, x) || x<=a)
		{
			dodaj(glo);
			reklew(x+1, b, stos.size());
		}
	}
}

int main()
{
	scanf("%d%d", &n, &m);
	for (int i=1; i<=n; i++)
		scanf("%s", wcz[i]+1);
	scanf("%d%d", &sta.first, &sta.second);
	scanf("%d%d", &kon.first, &kon.second);
	for (int i=1; i<=n; i++)
		for (int j=1; j<m; j++)
			if (wcz[i][j]!=wcz[i][j+1])
				edge({i-1, j}, {i, j});
	for (int i=1; i<n; i++)
		for (int j=1; j<=m; j++)
			if (wcz[i][j]!=wcz[i+1][j])
				edge({i, j-1}, {i, j});
	
	{
		for (int i=1; i<=m; i++)
			brzeg.push_back({0, i});
		for (int i=1; i<=n; i++)
			brzeg.push_back({i, m});
		for (int i=1; i<=m; i++)
			brzeg.push_back({n, m-i});
		for (int i=1; i<=n; i++)
			brzeg.push_back({n-i, 0});
	}
	while(brzeg[0]!=sta)
	{
		pii wez=brzeg[0];
		brzeg.push_back(wez);
		brzeg.erase(brzeg.begin());
	}
	
	{
		int g=wbrzegu(kon);
		assert(g>=0);
		for (int i=0; i<=g; i++)
			lewy.push_back(brzeg[i]);
		prawy.push_back(sta);
		for (int i=(int)brzeg.size()-1; i>=g; i--)
			prawy.push_back(brzeg[i]);
	}
	
	for (int i=0; i<=n; i++)
		for (int j=0; j<=m; j++)
			if ((int)graf[i][j].size()>2)
				ans(0);
	
	debug() << imie(lewy);
	debug() << imie(prawy);
	
	for (pii i : brzeg)
	{
		if (graf[i.first][i.second].empty())
			continue;
		pii ost{-1, -1};
		pii v=i;
		vector<pii> ter{v};
		while((int)ter.size()==1 || wbrzegu(ter.back())==-1)
		{
			pii u;
			for (pii i : graf[v.first][v.second])
				if (i!=ost)
					u=i;
			ost=v;
			v=u;
			ter.push_back(v);
		}
		if (wbrzegu(ter.back())<wbrzegu(i))
			continue;
		krawedzie-=((int)ter.size())-1;
		debug() << ter;
		bomble.push_back(ter);
	}
	if (krawedzie)
		ans(0);
	
	int num=-1;
	for (auto &i : bomble)
	{
		num++;
		if (i[0]==sta && i.back()==kon)
		{
			if ((int)bomble.size()>1)
				ans(0);
			wyn=i;
			ans(1);
		}
		if (i[0]==sta)
		{
			pii x=lokalizuj(i.back());
			if (x.first)
			{
				lacz_zmiana(0, x.second, num);
			}
			else
			{
				reverse(i.begin(), i.end());
				lacz_zmiana(x.second, 0, num);
			}
			continue;
		}
		if (i.back()==kon)
			reverse(i.begin(), i.end());
		
		if (i[0]==kon)
		{
			pii x=lokalizuj(i.back());
			if (x.first)
			{
				lacz_zmiana(((int)lewy.size())-1, x.second, num);
			}
			else
			{
				reverse(i.begin(), i.end());
				lacz_zmiana(x.second, ((int)prawy.size())-1, num);
			}
			continue;
		}
		
		pii x=lokalizuj(i[0]);
		pii y=lokalizuj(i.back());
		
		if (x.first!=y.first)
		{
			if (x.first)
			{
				swap(x, y);
				reverse(i.begin(), i.end());
			}
			lacz_zmiana(x.second, y.second, num);
			continue;
		}
		
		if (x.second>y.second)
		{
			swap(x, y);
			reverse(i.begin(), i.end());
		}
		
		if (!x.first)
		{
			zlewej[x.second].push_back({{0, y.second}, num});
			//czy potrzebne w druga strone?
		}
		else
		{
			zprawej[x.second].push_back({{1, y.second}, num});
			//czy potrzebne w druga strone?
		}
	}
	
	
	for (pii i : lewy)
		nalew[i.first][i.second]=1;
	for (pii i : prawy)
		napra[i.first][i.second]=1;
	
	num=-1;
	for (pii i : lewy)
		numlew[i.first][i.second]=(++num);
	num=-1;
	for (pii i : prawy)
		numpra[i.first][i.second]=(++num);
	
	for (int i=0; i<(int)lewy.size(); i++)
		debug() << imie(i) << imie(zlewej[i]);
	
	for (int i=0; i<(int)prawy.size(); i++)
		debug() << imie(i) << imie(zprawej[i]);
	
	reklew(0, 0, 0);
	rollback(0);
	rekpra(0, 0, 0);
	ans(0);
	
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define fr(i,a,b) for(int i=(a);i<=(b);++i)
#define rp(i,a,b) for(int i=(a);i>=(b);--i)
const int N=4e5+5,inf=1e9;
int n,X[N],Y[N],mx[4],L,ans[N],A[N],B[N];vector<int>now,tp;
inline int dis1(int i,int j) {return abs(X[i]-X[j])+abs(Y[i]-Y[j]);}
inline int dis2(int i,int j) {return max(abs(X[i]-X[j]),abs(Y[i]-Y[j]));}
int main() {
	scanf("%d",&n);
	fr(i,1,n) {
		scanf("%d%d",X+i,Y+i);
		int z[4]={X[i]+Y[i],X[i]-Y[i],-X[i]+Y[i],-X[i]-Y[i]},d=0,dd=inf;
		if(i!=1) fr(j,0,3) d=max(d,mx[j]-z[j]),mx[j]=max(mx[j],z[j]);
		else fr(j,0,3) mx[j]=z[j],d=0;A[i]=d;L=max(L,d);
		rp(j,i-1,1) {
			dd=min(dd,dis2(j,i));
			if(dd*2<d) break;
		}
		B[i]=dd;
		if(dd*2>=d) rp(j,i-1,1) if(dis1(j,i)==d&&dis2(j,i)==dd) ++ans[i];
		vector<int>().swap(tp);
		for(int x:now) {
			int d1=dis1(x,i),d2=dis2(x,i);
			if(d1>A[x]||d2<B[x]) ans[x]=0,A[x]=max(A[x],d1),B[x]=min(B[x],d2);
			if(d1>=A[x]&&d2<=B[x]) ++ans[x];
			if(d2*2>=d1) tp.push_back(x);
		}
		swap(now,tp);
		if(dd*2>=d) now.push_back(i);
		int anss=0;
		for(int x:now) anss+=ans[x];
		printf("%d\n",anss);
	}
	return 0;
}

#include<bits/stdc++.h>
using namespace std;using ll=long long;
int rd(int x=0,char c=getchar()){int f=1;while(!isdigit(c))f=(c^'-'?1:-1),c=getchar();while(isdigit(c))x=x*10+(c^48),c=getchar();return x*f;}
const int N=404;
int n,k,mod;
int f[N<<1][N][N],g[N<<1][N][N],F[N][N],G[N];
int fac[N<<1],inv[N<<1];
int C(int x,int y){return (ll)fac[x]*inv[y]%mod*inv[x-y]%mod;}
int jx[N];
void add(int&x,ll y){x=(x+y)%mod;}
int main(){
	n=rd(),k=rd(),mod=rd();
	fac[0]=inv[0]=inv[1]=jx[0]=1;
	for(int i=1;i<=2*n;i++)fac[i]=(ll)fac[i-1]*i%mod;
	for(int i=2;i<=2*n;i++)inv[i]=(ll)(mod-mod/i)*inv[mod%i]%mod;
	for(int i=2;i<=2*n;i++)inv[i]=(ll)inv[i]*inv[i-1]%mod;
	for(int i=1;i<=n;i++)jx[i]=(ll)jx[i-1]*(2*i-1)%mod;
	for(int j=0;j<=n;j++)f[0][j][j]=fac[j];
	for(int i=0;i<=2*n;i++){
		for(int j=0;j<=n;j++){
			for(int k=0;k<=n&&i+j+k<=2*n;k++)if(f[i][j][k]){
				add(f[i+2][j][k],(ll)f[i][j][k]*(i+1));
				add(f[i+1][j+1][k],(ll)f[i][j][k]*(j+1));
				add(f[i+1][j][k+1],(ll)f[i][j][k]*(k+1));
			}
		}
	}
	for(int j=0;j<=2*n&&j<=n;j++)g[0][j][0]=1;
	for(int k=0;k<=n;k++){
		for(int i=0;i<=2*n;i++){
			for(int j=0;i+j<=2*n&&j<=n;j++)if(g[i][j][k]){
				add(g[i+2][j][k+1],(ll)g[i][j][k]*(i+1));
				add(g[i+1][j+1][k+1],(ll)g[i][j][k]*(j+1));
				add(g[i+1][j][k],g[i][j][k]);
			}
		}
	}
	G[0]=1;
	for(int st=1;st<=k;st++){
		if(st&1){
			memset(F,0,sizeof(F));
			for(int i=0;i<=n;i++)if(G[i])
				for(int j=0;j*2<=i;j++)for(int k=0;k*2<=i;k++)
					add(F[j][k],(ll)C(i,2*j)*C(i,2*k)%mod*jx[j]%mod*jx[k]%mod*f[2*(n-i)][i-2*j][i-2*k]%mod*G[i]);
		}
		else{
			memset(G,0,sizeof(G));
			for(int j=0;j*2<=n;j++)for(int k=max(0,2*j-n);k*2<=n;k++)if(F[j][k])
				for(int i=max(j,k);i<=n&&i*2<=n+j+k;i++)
					add(G[i],(ll)F[j][k]*g[n-2*j+k][j][i-j]%mod*g[n+j-2*k][k][i-k]%mod*fac[n+j+k-2*i]);
		}
	}
	int ans=0;
	if(k&1)for(int i=0;i<=n;i++)for(int j=0;j<=n;j++)ans=(ans+F[i][j])%mod;
	else for(int i=0;i<=n;i++)ans=(ans+G[i])%mod;
	printf("%d",ans);
	return 0;
}

