using namespace std;
int T,n,q,fa[N][21];ll faW[N][21];
int mx[N][21];
vector<pii> G[N];
int dep[N];ll wdep[N];
int dfn[N],siz[N],clk,rk[N];
void dfs(int u,int F)
{
	dep[u]=dep[F]+1;fa[u][0]=F;for(int i=1;i<=20;++i)fa[u][i]=fa[fa[u][i-1]][i-1];
	for(int i=1;i<=20;++i)faW[u][i]=faW[fa[u][i-1]][i-1]+faW[u][i-1];
	for(int i=1;i<=20;++i)mx[u][i]=max(mx[u][i-1],mx[fa[u][i-1]][i-1]);
	dfn[u]=++clk;siz[u]=1;rk[clk]=u;
	for(auto [v,w]:G[u])if(v^F)
	{
		wdep[v]=wdep[u]+w;
		faW[v][0]=w;
		mx[v][0]=w;
		dfs(v,u);
		siz[u]+=siz[v];
	}
}
int lca(int u,int v)
{
	if(dep[u]<dep[v])swap(u,v);
	for(int i=20;~i;--i)if(dep[u]-(1<<i)>=dep[v])u=fa[u][i];if(u==v)return u;
	for(int i=20;~i;--i)if(fa[u][i]^fa[v][i])u=fa[u][i],v=fa[v][i];return fa[u][0];
}
inline ll dis(int u,int v,int L=0)
{
	if(!L)L=lca(u,v);return wdep[u]+wdep[v]-2*wdep[L];
}
pii anc(int u,ll k)
{
	for(int i=20;~i;--i)if(dep[u]-(1<<i)>=1&&k>=faW[u][i])k-=faW[u][i],u=fa[u][i];
	return pii(u,k);
}
pii tok(int u,int v,ll k)
{
	int L=lca(u,v);
	if(wdep[u]-wdep[L]>=k)return anc(u,k);
	else return anc(v,dis(u,v,L)-k);
}
inline bool insub(int u,int v)
{
	return dfn[u]<=dfn[v]&&dfn[v]<dfn[u]+siz[u];
}
inline int fork(int x,int y,int z)
{
	int L1=lca(x,y),L2=lca(y,z),L3=lca(z,x);
	if(dep[L1]>=dep[L2]&&dep[L1]>=dep[L3])return L1;
	return dep[L2]>=dep[L3]?L2:L3;
}
inline int pthmx(int u,int v)
{
	if(dep[u]<dep[v])swap(u,v);
	int ans=0;
	for(int i=20;~i;--i)if(dep[u]-(1<<i)>=dep[v])ans=max(ans,mx[u][i]),u=fa[u][i];if(u==v)return ans;
	for(int i=20;~i;--i)if(fa[u][i]^fa[v][i])ans=max({ans,mx[u][i],mx[v][i]}),u=fa[u][i],v=fa[v][i];
	return max({ans,mx[u][0],mx[v][0]});
}
ll solve(int s1,int t1,int s2,int t2)
{
	int x=fork(s1,s2,t2),y=fork(t1,s2,t2);
	if(x==y)return max(dis(s1,t1),dis(s2,t2));
	bool isx1=dis(s1,x)<=dis(s1,y),isx2=dis(s2,x)<=dis(s2,y);
	if(isx1==isx2)
	{
		if(!isx1)swap(x,y);
		ll ds1=dis(s1,x),ds2=dis(s2,x);
		ll dt1=dis(x,t1),dt2=dis(x,t2);
		int w=pthmx(x,y);
		ll ans1=max(ds1+dt1,max(ds2,ds1+w)+dt2);
		ll ans2=max(ds2+dt2,max(ds1,ds2+w)+dt1);
		return min(ans1,ans2);
	}
	else
	{
		ll d=dis(s1,s2);
		pii m1=tok(s1,t1,d/2),m2=tok(s2,t2,d/2);
		if(m1!=m2||!m1.second)return max(dis(s1,t1),dis(s2,t2));
		int a=m1.first,b=fa[a][0];
		ll ans1=max(dis(s1,a),dis(s2,a))+max(dis(t1,a),dis(t2,a));
		ll ans2=max(dis(s1,b),dis(s2,b))+max(dis(t1,b),dis(t2,b));
		return min(ans1,ans2);
	}
}
