	c[a[x]]+=k;
	S.add(x,k,1,n,rt[a[x]]),S.add(x,-k,1,n,rt[(a[x]+m-1)%m]);
	upd(a[x]),upd((a[x]+m-1)%m);
	T.upd(a[x]),T.upd((a[x]+m-1)%m);
}
