int f[1<<15][31],g[1<<15][31],dpr[31][31][31];const int p=998244353;
void init()
{
	for(int i=0;i<30;++i)
	{
		for(int x=0;x<=i;++x)
		{
			for(int y=x;y<30;++y)
			{
				if(i==y)dpr[i][x][y]=(1<<i)%p;
				if(i)for(int z=x;z<=y;++z)dpr[i][x][y]=(dpr[i][x][y]+1ll*dpr[i-1][x][z]*dpr[i-1][z][y])%p;
			}
		}
	}
	f[0][0]=1;
	for(int S=1;S<1<<15;++S)
	{
		int hi=31-__builtin_clz(S);
		for(int i=0;i<30;++i)
		{
			for(int j=0;j<=i;++j)f[S][i]=(f[S][i]+1ll*f[S^1<<hi][j]*dpr[hi][j][i])%p;
		}
	}
	for(int i=0;i<30;++i)g[0][i]=1;
	for(int S=1;S<1<<15;++S)
	{
		int lo=__lg(S&-S);
		for(int i=0;i<30;++i)
		{
			for(int j=i;j<30;++j)g[S][i]=(g[S][i]+1ll*g[S^1<<lo][j]*dpr[lo+15][i][j])%p;
		}
	}
}
int solve(int n)
{
	unsigned long long ans=0;
	for(int i=0;i<15;++i)ans+=1ll*f[n&(1<<15)-1][i]*g[n>>15][i];
	return ans%p;
}
