			a[i] = p[i];
			b[i] = r[i] - l[i];
		}
		work(0, n - 1);
		for(i = 0; i < 2 * n; i++)
			ans.c[i] = (ans.c[i] + c[i + 1]) % mod;
		for(i = 0; i < n - 1; i++)
			ans.c[2 * i] = (ans.c[2 * i] + p[i] * (1 - l[i])) % mod;
		for(i = 0; i <= 2 * n; i++)
