		for(i = 0; i < n - 1; i++)
		{
			a[i] = mod - l[i];
			b[i] = p[i] * (1 - l[i]);
		}
		work(0, n - 2);
		for(i = 0; i <= 2 * n; i++)
			ans.c[i] = (ans.c[i] + c[i]) % mod;
		for(i = 0; i < n - 1; i++)
			ans.c[i] = (ans.c[i] + p[i] * r[i]) % mod;
		for(i = 0; i <= 2 * n; i++)
			c[i] = 0;
		for(i = 0; i < n - 1; i++)
		{
			a[i] = r[i];
			b[i] = p[i] * r[i];
		}
		work(0, n - 2);
		for(i = 0; i <= 2 * n; i++)
			ans.c[i] = (ans.c[i] + c[i]) % mod;
		for(i = 0; i <= 2 * n; i++)
