using namespace std;
const int N=2e5+5;
int n,k,a[N],b[N];
int cnt[N<<2],maxx[N<<2],sum[N<<2],tag[N<<2];
#define ls o*2
#define rs o*2+1
#define mid (l+r)/2
void add(int o,int k)
{
	tag[o]+=k;
	maxx[o]+=k;
	sum[o]+=k*cnt[o];
}
void pushdown(int o)
{
	add(ls,tag[o]);
	add(rs,tag[o]);
	tag[o]=0;
}
void pushup(int o)
{
	maxx[o]=max(maxx[ls],maxx[rs]);
	cnt[o]=cnt[ls]+cnt[rs];
	sum[o]=sum[ls]+sum[rs];
}
void build(int o=1,int l=1,int r=n)
{
	tag[o]=0;
	if(l==r)
	{
		tag[o]+=b[l];
		if(tag[o]<0){cnt[o]=1;sum[o]=maxx[o]=tag[o];}
		else{cnt[o]=sum[o]=0;maxx[o]=-1e18;}
		return;
	}
	build(ls,l,mid);build(rs,mid+1,r);
	pushup(o);
}
void update(int lx,int rx,int k,int o=1,int l=1,int r=n)
{
	if(lx<=l&&r<=rx)
	{
		if(l==r)
		{
			tag[o]+=k;
			if(tag[o]<0){cnt[o]=1;sum[o]=maxx[o]=tag[o];}
			else{cnt[o]=sum[o]=0;maxx[o]=-1e18;}
			return;
		}
		if(maxx[o]+k<0)
		{
			add(o,k);
			return;
		}
	}
	pushdown(o);
	if(lx<=mid)update(lx,rx,k,ls,l,mid);
	if(rx>mid)update(lx,rx,k,rs,mid+1,r);
	pushup(o);
}
void solve()
{
	cin>>n>>k;
	for(int i=1;i<=n;i++)cin>>a[i];
	for(int i=1;i<n;i++)b[i]=a[i+1]-a[i];
	b[n]=0;
	build();
	cout<<(a[1]+sum[1]>=0?"YES\n":"NO\n");
	while(k--)
	{
		int l,r,s,d;cin>>l>>r>>s>>d;
		if(l==1)a[1]+=s;
		else update(l-1,l-1,s);
		if(l<r)update(l,r-1,d);
		if(r<n)update(r,r,-s-(r-l)*d);
		cout<<(a[1]+sum[1]>=0?"YES\n":"NO\n");
	}
}
