ll pw1[N],pw2[N];
vector<int>c[N],e[N],ad[N];
struct Hash{
    ll a,b;
    Hash(int x=0){a=b=x%mod;}
    Hash(ll x,ll y){a=x,b=y;}
    Hash operator+(const Hash&t){return Hash((a+t.a)%mod,(b+t.b)%mod);}
    Hash operator-(const Hash&t){return Hash((a-t.a+mod)%mod,(b-t.b+mod)%mod);}
    Hash operator*(const int&t){return Hash(a*pw1[t]%mod,b*pw2[t]%mod);}
    bool operator<(const Hash&t)const{return pi(a,b)<pi(t.a,t.b);}
    friend ostream&operator<<(ostream&o,Hash t){return o<<'('<<t.a<<','<<t.b<<')';}
}A[N],B[N],C[N];
map<array<Hash,3>,int>mp;
int Min(int x,int y){return dep[x]<dep[y]?x:y;}
int lca(int x,int y) {
    if(x==y)return x;x=L[x],y=L[y];if(x>y)swap(x,y);
    int k=__lg(y-x);return fa[Min(mx[k][x+1],mx[k][y-(1<<k)+1])];
}
void dfs(int x) {
    L[x]=++sn,mx[0][sn]=x,sz[x]=1;
    for(int y:e[x])fa[y]=x,dep[y]=dep[x]+1,dfs(y),sz[x]+=sz[y];
}
void getH(int x) {
    A[x]=Hash(sz[x]),B[x]=Hash(a[x]),C[x]=Hash();
    for(int y:e[x]) {
        getH(y);
        A[x]=A[x]*sz[y]+A[y];
        B[x]=B[x]*sz[y]+B[y];
        C[x]=C[x]*sz[y]+C[y];
    }
    int R=L[x]+sz[x]-1;
    for(int i:ad[x])for(int j:c[i])B[x]=B[x]-Hash(i)*(R-L[j]),C[x]=C[x]+Hash(b[j])*(R-L[j]);
    mp[{A[x],B[x],C[x]}]++;
}
void solve() {
    cin>>n,sn=0,mp.clear();
    for(int i=1;i<=n;i++)e[i].clear(),c[i].clear(),ad[i].clear();
    for(int i=1;i<=n;i++)cin>>a[i],c[a[i]].push_back(i);
    for(int i=1,k;i<=n;i++) {
