auto rcmp = [](auto a, auto b) { return get<0>(a) * (__int128_t)get<1>(b) < get<0>(b) * (__int128_t)get<1>(a); };

constexpr int mod = 1e9 + 7;

int inv(int a) { int r = 1, b = mod - 2; for (; b; b /= 2, a = a * (uint64_t)a % mod) if (b % 2) r = r * (uint64_t)a % mod; return r; }

int main() {
  cin.tie(0)->sync_with_stdio(0);
  int n, q; cin >> n >> q;
  vector<ii> pts(n);
  for (auto& [a, b]: pts) cin >> a >> b;
  sort(pts.begin(), pts.end(), [](auto a, auto b) { return pair{!a, b} < pair{!b, a}; });
  vector<vector<tuple<int64_t, int, int, int64_t>>> ch(n);
  for (int i = 0; i < n; ++i) {
    vector<tuple<int64_t, int, int>> chp;
    for (int j = 0; j < n; ++j) {
      int64_t p = !pts[j] - !pts[i], q = pts[j][0] - pts[i][0] << 1;
      if (q < 0) p = -p, q = -q;
      if (q && p > 0 && p < (int)1e9 * q) chp.emplace_back(p, q, i < j);
    }
    sort(chp.begin(), chp.end(), rcmp);
    int j = i;
    for (auto& [p, q, d]: chp) {
      d? ch[j++].push_back({p, q, pts[i][0], -!pts[i]}):
         ch[--j].push_back({p, q, -pts[i][0], !pts[i]});
    }
  }
  vector<int> ans(q), t(q);
  vector<vector<ii>> qs(n);
  for (int i = 0, a, b, c; i < q; ++i) cin >> a >> b >> c, --c, qs[c].insert(qs[c].end(), {{a, 2 * i}, {b, 2 * i + 1}}), t[i] = b - a;
  for (int i = 0, b1 = 0, b0 = 0; i < n; ++i) {
    sort(qs[i].begin(), qs[i].end());
    sort(ch[i].begin(), ch[i].end(), rcmp);
    int a1 = b1 = (b1 + (mod - pts[i][0])) % mod, a0 = b0 = (b0 + !pts[i]) % mod, c = 0, l = 0, ll = 0, lll = 0;
    auto step = [&](int r) {
      int rr = r * (uint64_t)r % mod, rrr = rr * (uint64_t)r % mod;
      c = (c + (i + 1) * 1ull * (mod + rrr - lll) + a1 * 3ull * (mod + rr - ll) + a0 * 3ull * (mod + r - l)) % mod;
      l = r, ll = rr, lll = rrr;
    };
    for (int j = 0, k = 0; j < qs[i].size(); ++j) {
      while (k < ch[i].size() && get<0>(ch[i][k]) < get<1>(ch[i][k]) * (uint64_t)qs[i][j][0]) {
        step(get<0>(ch[i][k]) % mod * inv(get<1>(ch[i][k])) % mod);
        a1 = (a1 + get<2>(ch[i][k]) + 1u * mod) % mod;
        a0 = (a0 + get<3>(ch[i][k]) + 2ull * mod * mod) % mod;
        ++k;
      }
      step(qs[i][j][0]);
      if (j + 1 < qs[i].size() && qs[i][j + 1] == ii{qs[i][j][0], qs[i][j][1] | 1}) {
        ans[qs[i][j][1] / 2] = ((i + 1ull) * ll + a1 * 2ull * l + a0) % mod, ++j;
      } else {
        ans[qs[i][j][1] / 2] = (ans[qs[i][j][1] / 2] + c * (qs[i][j][1] % 2 ?: mod - 1ull)) % mod;
      }
    }
  }
