{
	h = -1e18;
	int n, q, d = 0;
	cin >> n >> q;
	for (int i = 1; i <= n; i++) {
		cin >> a[i];
		c[i] = c[i - 1] + a[i];
	}
	f[0] = 1; g[n + 1] = n;
	for (int i = 1; i <= n; i++) {	
		if (c[i] < c[f[i - 1] - 1]) f[i] = i + 1;
		else f[i] = f[i - 1];
		if (c[i] - c[f[i] - 1] > h) {
			h = c[i] - c[f[i] - 1];
			d = 1;
		}
		else if (c[i] - c[f[i] - 1] == h) d++;
	}
	for (int i = n; i >= 1; i--) {
		if (c[g[i + 1]] < c[i - 1]) g[i] = i - 1;
		else g[i] = g[i + 1];
	}
	if (h == 0) d++;
	long long int k = 0, l = 0;
	for (int i = 1; i <= n; i++) {
		if (k <= 0) {
			k = 0; l = i;
		}
		k += a[i];
		if (k == h) ff[i] = l;
		else ff[i] = ff[i - 1];
	}
	k = l = 0; gg[n + 1] = 0;
	for (int i = n; i >= 1; i--) {
