void dfs(int u,int fa)
{
	inq[u]=1;sz[u]=1;
	dfn[u]=low[u]=++cnt;
	int ct[3]={0};
	for(auto v:g[u])
		if(v!=fa)
		{
			if(!dfn[v])
			{
				dfs(v,u);
				low[u]=min(low[u],low[v]);
				sz[u]+=sz[v];
				if(low[v]>=dfn[u])
				{
					if(sz[v]%3==1)++ct[2];
				}
				else
					++ct[f[v]];
			}
			else if(inq[u])
				low[u]=min(low[u],dfn[v]);
		}
	if(sz[u]%3==2)fl=1;
	else if(sz[u]%3==1)
	{
		if(ct[1]>1)fl=1;
		f[u]=1;
	}
	else
	{
		if(ct[1])fl=1;
		f[u]=0;
	}
	inq[u]=0;
}

