inline int H(int l,int r,int maxx=0)
{
	int P=l;
	for(int i=17;i>=0;i--)
	{
		if(P+(1<<i)-1<=r&&f[i][P]<maxx)
		{
			P+=1<<i;
		}
	}
	if(P>r)
	{
		return 0;
	}
	int t=__lg(r-P+1);
	return ((long long)p[P-l]*h[t][P]+(long long)
	p[P+(1<<t)-l]*H(P+(1<<t),r,f[t][P]))%mod;
}
