		for(int i=0;i<lim;i++) if(rev[i]<i) swap(a[i],a[rev[i]]);
		for(int l=2,t=1;l<=lim;l<<=1,t++){
			int i=l>>1;
			for(int j=0;j<lim;j+=l) for(int k=0;k<i;++k){
				int x=(1ll*a[i+j+k]*ipw[t][k])%mod;
				a[i+j+k]=(a[j+k]+mod-x)%mod;
				a[j+k]=(a[j+k]+x)%mod;
			}
		}
		if(flag==-1){
			reverse(a+1,a+lim);
			int inv=ksm(lim,mod-2);
			for(int i=0;i<lim;i++) a[i]=(1ll*a[i]*inv)%mod;
		}
		return;
	}
	vector<int> do_ntt(vector<int> v1,vector<int> v2){
		vector<int> ret;
		n=v1.size(),m=v2.size();
		resnum=n+m-1;
		for(lim=1,mxbit=0;lim<n+m;lim<<=1,mxbit++);
		--mxbit;
		for(int i=0;i<lim;++i) a1[i]=a2[i]=0;
		for(int i=0;i<n;++i) a1[i]=v1[i];
		for(int i=0;i<m;++i) a2[i]=v2[i];
		rev[0]=0;
		for(int i=1;i<lim;++i) rev[i]=(rev[i>>1]>>1)|((i&1)<<mxbit);
		NTT(a1,1),NTT(a2,1);
		for(int i=0;i<lim;++i) a1[i]=(1ll*a1[i]*a2[i])%mod;
		NTT(a1,-1);
		for(int i=0;i<resnum;++i) ret.push_back(a1[i]);
		return ret;
	}
}ntt;
