int getcoef(int l,int r,int x){
	int v=(1ll*x*(r-x)+1ll*(l+x-1)*(x-l)/2)%(mod-1);
	v=(v+mod-1)%(mod-1);
	v=ksm(g,v);
	if((r-x)&1) v=mod-v;
	v=(1ll*v*pre[r-x])%mod;
	v=(1ll*v*pre[x-l])%mod;
	return ksm(v,mod-2);
}
