	if(dep[x]<dep[y])swap(x,y);
	for(int i=19;~i;--i)if(dep[fa[x][i]]>=dep[y])x=fa[x][i];
	if(x==y)return x;
	for(int i=19;~i;--i)if(fa[x][i]!=fa[y][i])x=fa[x][i],y=fa[y][i];
