void getrt(int u,int fa)
{
	int ax=0;sz[u]=1;
	d[q[++tl]=u]=d[fa]+1;
	axd=max(axd,d[u]);
	for(auto v:e[u])
		if(!vis[v]&&v!=fa)
		{
			d[v]=d[u]+1;
			getrt(v,u);
			sz[u]+=sz[v];
			ax=max(ax,sz[v]);
		}
	ax=max(ax,al-sz[u]);
	if(ax<=al/2)rt=u;
}
void sol(int u)
{
	int i;
	vis[u]=1;d[0]=-1;tl=0;axd=0;getrt(u,0);
	vector<ll>A;A.resize(axd+1);
	for(i=1;i<=tl;++i)++A[d[q[i]]];
	A=A*A;for(i=1;i<A.size();++i)(c[i]+=A[i])%=mod;
	for(auto v:e[u])
		if(!vis[v])
		{
			tl=0;axd=0;getrt(v,u);
			A.clear();A.resize(axd+1);
			for(i=1;i<=tl;++i)++A[d[q[i]]];
			A=A*A;for(i=1;i<A.size();++i)(c[i]-=A[i])%=mod;
		}
	for(auto v:e[u])
		if(!vis[v])
			{al=sz[v];tl=0;getrt(v,u);sol(rt);};
}

