ld calc(int rid,ll ad)
{
    ll rA=r[rid-1],rB=r[rid];
    ld ang=pi*2*abs(ad)/M,dg=acos(ld(rA)/rB);
    if(ang>dg)return sqrt(rB*rB-rA*rA)+rA*(ang-dg);
    return sqrt(rA*rA+rB*rB-rA*rB*cos(ang)*2);
}
void qry(int rid,int cid,int pl,int pr)
{
    for(int i=pl,pos=Mix[rid][cid].first;i<=pr;i++)
    {
        auto&[a,r2]=ps[i];ld V=r2+calc(rid,pos-a);
        if(V<Vr[cid])Vr[cid]=V,Vp[cid]=i;
    }
}
