const int N=1e5+10,M=N*6;
int n,m;
struct BIT{
  unsigned c[N];
  void add(int x,unsigned y){
    for(x++;x;x^=x&-x)c[x]+=y;
  }
  unsigned get(int x,unsigned y=0){
    for(x++;x<=n+1;x+=x&-x)y+=c[x];
    return y;
  }
  void update(int l,int r,unsigned x){
    add(r,x);
    add(l-1,-x);
  }
  void clr(int x){
    for(x++;x;x^=x&-x)c[x]=0;
  }
}A,B,C;
int n1,n2;
struct opts{
  int op,l,r;
  unsigned w;
