#include <bits/stdc++.h>

using ll = long long;
using db = double;

const int N = 1e5 + 10, V = 1e6 + 10;
const db pi = std::acos(-1.0), eps = 1e-7, inf = 1e10;

struct point {
	db x, y;
	point(db _x = 0, db _y = 0) : x(_x), y(_y) {}
	point operator - (point k) { return point(x - k.x, y - k.y); }
	friend db operator * (point a, point b) { return a.x * b.y - a.y * b.x; }
	db ang() { db now = std::atan2(y, x); if (now < 0) now += 2 * pi; return now; }
	db dis() { return sqrt(x * x + y * y); }
} st;
using pS = std::vector<point>;

int n; db r;
struct rectangle { 
	db x1, y1, x2, y2;
	bool inside(db x, db y) { return 2 * x1 < x && x < 2 * x2 && 2 * y1 < y && y < 2 * y2; }
} rec[N];

struct line { db p, u, v; }; 
using lineS = std::vector<line>;

void solve() {
	std::cin >> r >> n;
	for (int i = 1; i <= n; i++) std::cin >> rec[i].x1 >> rec[i].y1 >> rec[i].x2 >> rec[i].y2;
	std::cin >> st.x >> st.y;
	bool f[4] = {1, 1, 1, 1};
	lineS v1, v2;
	auto add1 = [&](db x, db y1, db y2) -> void { v1.push_back({x, y1, y2}); };
	auto add2 = [&](db y, db x1, db x2) -> void { v2.push_back({y, x1, x2}); };
	for (int i = 1; i <= n; i++) {
		auto [x1, y1, x2, y2] = rec[i];
		if (rec[i].inside(2 * st.x + 1, 2 * st.y + 1)) f[0] = 0;
		if (rec[i].inside(2 * st.x - 1, 2 * st.y + 1)) f[1] = 0;
		if (rec[i].inside(2 * st.x - 1, 2 * st.y - 1)) f[2] = 0;
		if (rec[i].inside(2 * st.x + 1, 2 * st.y - 1)) f[3] = 0;
		if (x2 < st.x) add1(x2, y2, y1);
		if (st.x < x1) add1(x1, y1, y2);
		if (y2 < st.y) add2(y2, x1, x2);
		if (st.y < y1) add2(y1, x2, x1);
	}
	auto calc = [&](lineS &v, bool w) -> lineS {
		lineS ret;
		std::set<std::pair<db, db>> s;
		s.insert({0, pi / 2}), s.insert({pi / 2, pi});
		s.insert({pi, pi * 3 / 2}), s.insert({pi * 3 / 2, pi * 2});
		db pivot = w ? st.y : st.x;
		std::sort(v.begin(), v.end(), [&](line &l1, line &l2) {
			int w1 = l1.p < pivot, w2 = l2.p < pivot;
			if (w1 != w2) return w1 > w2;
			return w1 ? (l1.p > l2.p) : (l1.p < l2.p);
		});
		auto ins = [&](db a1, db a2, db val) -> void {
			if (a1 + eps > a2) return;
			while (1) {
				auto it = s.lower_bound({a1, 0});
				// if (it != s.end()) {
				// 	std::cout << (*it).first << " " << (*it).second << std::endl;
				// }
				if (it == s.end() || (*it).second <= a1 || a2 <= (*it).first) {
					if (it == s.begin()) break;
					it--;
				}
				if ((*it).second <= a1 || a2 <= (*it).first) break;
				auto [l, r] = *it; s.erase(it);
				db L = std::max(l, a1), R = std::min(r, a2);
				ret.push_back({val, L, R});
				if (l < L) s.insert({l, L});
				if (R < r) s.insert({R, r});
			}
		};
		for (auto [p, u, v] : v) {
			point p1, p2;
			if (!w) p1 = point(p, u), p2 = point(p, v);
			else p1 = point(u, p), p2 = point(v, p);
			db a1 = (p1 - st).ang(), a2 = (p2 - st).ang();
			if (a1 < a2) ins(a1, a2, p);
			else ins(a1, 2 * pi, p), ins(0, a2, p);
		}
		for (auto [l, r] : s) ret.push_back({inf, l ,r});
		std::sort(ret.begin(), ret.end(), [&](line &l1, line &l2) { 
			return l1.u < l2.u;
		});
		return ret;
	};
	lineS vx = calc(v1, 0);
	lineS vy = calc(v2, 1);
	db angl = 0, angr, angm, ans = 0;
	auto getpoint = [&](db ang) -> point {
		db x = st.x, y = st.y;
		db dx = std::cos(ang), dy = std::sin(ang);
		db a = (db)dx * dx + (db)dy * dy;
		db b = (db)2 * x * dx + (db)2 * y * dy;
		db c = (db)x * x + (db)y * y - (db)r * r;
		db k = (-b + std::sqrt(b * b - 4 * a * c)) / (2 * a);
		return point(x + k * dx, y + k * dy);
	};
	auto getS = [&](db d) -> db {
		double alpha = std::asin(d / (2 * r));
		return alpha * r * r - r * r * std::sin(alpha) * std::cos(alpha);
	};
	auto calc1 = [&](db a1, db a2) -> db {
		point p1 = getpoint(a1), p2 = getpoint(a2);
		return ((p1 - st) * (p2 - st)) / 2 + getS((p1 - p2).dis());
	};
	auto work = [&](db a1, db a2, db x, db y) {
		db ret = calc1(a1, a2);
		point dir1 = point(std::cos(a1), std::sin(a1));
		point dir2 = point(std::cos(a2), std::sin(a2));
		if (x != inf) {
			db k1 = (x - st.x) / dir1.x;
			db k2 = (x - st.x) / dir2.x;
			db now = (dir1 * dir2) * k1 * k2 / 2;
			ret = std::min(ret, now);
		}
		if (y != inf) {
			db k1 = (y - st.y) / dir1.y;
			db k2 = (y - st.y) / dir2.y;
			db now = (dir1 * dir2) * k1 * k2 / 2;
			ret = std::min(ret, now);
		}
		ans += ret;
	};
	for (int i = 0, j = 0; i < vx.size() && j < vy.size();) {
		angr = std::min(vx[i].v, vy[j].v);
		int bl;
		if (angl < pi / 2) bl = 0;
		else if (angl < pi) bl = 1;
		else if (angl < pi * 3 / 2) bl = 2;
		else bl = 3;
		if (f[bl]) {
			bool bk = 0;
			if (vx[i].p != inf && vy[j].p != inf) {
				angm = (point(vx[i].p, vy[j].p) - st).ang();
				if (angl < angm && angm < angr) bk = 1;
			}
			if (bk) {
				work(angl, angm, vx[i].p, vy[j].p);
				work(angm, angr, vx[i].p, vy[j].p);
			}
			else {
				work(angl, angr, vx[i].p, vy[j].p);
