}
poly Inv(poly a) {
	poly ret(1), t, t2;
	assert(a[0]), ret[0] = Power(a[0], mod - 2);
	for (int l = 1; l < a.size(); l <<= 1)
		t2 = a, t2.resize(l << 1), t = t2 * ret, t.resize(l << 1), t = t * ret, t.resize(l << 1),
		ret = ret * 2 - t;
	return ret.resize(a.size()), ret;
}
poly pre(poly a, int n) {
