vector<poly> multiply2d(vector<poly> v1, vector<poly> v2) {
	int sz1 = 1, sz2 = 1;
	for (auto i : v1) sz1 = max(sz1, (int)i.size());
	for (auto i : v2) sz2 = max(sz2, (int)i.size());
	int sz = sz1 + sz2 - 1;
	vector<int> f1(v1.size() * sz), f2(v2.size() * sz);
	cerr << f1.size() << ' ' << f2.size() << endl;
	for (int i = 0; i < v1.size(); i++)
		for (int j = 0; j < v1[i].size(); j++) f1[i * sz + j] = v1[i][j];
	for (int i = 0; i < v2.size(); i++)
		for (int j = 0; j < v2[i].size(); j++) f2[i * sz + j] = v2[i][j];
	f1 = f1 * f2;
	vector<poly> res(v1.size() + v2.size() - 1, poly());
	for (int i = 0; i < res.size(); i++) {
		res[i].resize(sz);
		for (int j = 0; j < sz; j++) res[i][j] = f1[i * sz + j];
		while (res[i].size() > 1 && res[i].back() == 0) res[i].pop_back();
	}
	return res;
}
poly power_projection(poly f) {
	int n = f.size() - 1, k = 1;
	vector<vector<int>> P(n + 1, vector<int>(k + 1));
	vector<vector<int>> Q(n + 1, vector<int>(k + 1));
	Q[0][0] = 1;
	P[0][0] = 1;
	for (int i = 0; i <= n; i++) Q[i][1] = (mod - f[i]) % mod;
	while (n) {
		auto R = Q;
		for (int i = 1; i <= n; i += 2) R[i] = 0 - R[i];
		auto S = multiply2d(P, R);
		auto T = multiply2d(Q, R);
		vector<vector<int>> U(n / 2 + 1, vector<int>(k * 2 + 1));
		vector<vector<int>> V(n / 2 + 1, vector<int>(k * 2 + 1));
		for (int i = 0; i <= n / 2; i++) U[i] = S[i * 2 + n % 2], V[i] = T[i * 2];
		P = U, Q = V;
		n /= 2, k *= 2;
	}
	return pre(P[0] * Inv(Q[0]), f.size());
}
