	}
	for(int i=lim;i>=1;i--)
	{
		d[i]+=d[i+2]+d2[i+2],d2[i]+=d2[i+2];
		d[i]%=P,d2[i]%=P;
		ans[i]=(ans[i]+d[i])%P;
	}
}
