const ll MOD = 998244353;
ll p0w(ll x,ll e){
	ll p = 1;
	ll acc = x;
	while(e){
		if(e&1) p = p*acc%MOD;
		acc = acc*acc%MOD;
		e /= 2;
	}
	return p;
}
const array<ll,23> W = []{
	array<ll,23> W = {2200}; //order 2^23
	rep(i,0,22) W[i+1] = W[i]*W[i]%MOD;
