#include <bits/stdc++.h>

using namespace std;

const int MOD = 998244353;
const int G = 3;

int myPow(int a, int n) {
	int res = 1;
	while (n) {
		if (n & 1) res = 1LL * res * a % MOD;
		a = 1LL * a * a % MOD;
		n >>= 1;
	}
	return res;
}

void ntt(vector<int>& a, bool invert, int n) {
	for (int i = 1, j = 0; i < n; i++) {
		int bit = n >> 1;
		for (; j & bit; bit >>= 1) j ^= bit;
		j ^= bit;
		if (i < j) swap(a[i], a[j]);
	}
	
	for (int len = 2; len <= n; len <<= 1) {
		int wlen = myPow(G, (MOD - 1) / len);
		if (invert) wlen = myPow(wlen, MOD - 2);
		for (int i = 0; i < n; i += len) {
			int w = 1;
			for (int j = 0; j < len / 2; j++) {
				int u = a[i + j], v = 1LL * a[i + j + len / 2] * w % MOD;
				a[i + j] = (u + v) % MOD;
				a[i + j + len / 2] = (u - v + MOD) % MOD;
				w = 1LL * w * wlen % MOD;
			}
		}
	}
	
	if (invert) {
		int inv_n = myPow(n, MOD - 2);
		for (int& x : a) x = 1LL * x * inv_n % MOD;
	}
}

void convolve(vector<int>& a, vector<int>& b, vector<int>& res, int n) {
	vector<int> fa(a.begin(), a.end()), fb(b.begin(), b.end());
	fa.resize(n); fb.resize(n);
	
	ntt(fa, false, n);
	ntt(fb, false, n);
	
	for (int i = 0; i < n; i++) {
		fa[i] = 1LL * fa[i] * fb[i] % MOD;
	}
	
	ntt(fa, true, n);
	res = vector<int>(fa.begin(), fa.end());
}

void involve(vector<int>& f1, vector<int>& f2, vector<int>& res, int n) {
	convolve(f1, f2, res, n);
}

void solve() {
	int H, W, A, B, C, D;
	cin >> H >> W >> A >> B >> C >> D;
	vector<vector<int> > a(2, vector<int>(3, 0));
	a[0][0] = A - 1;
	a[0][1] = B - A + 1;
	a[0][2] = H - B;
	a[1][0] = C - 1;
	a[1][1] = D - C + 1;
	a[1][2] = W - D;
	vector<int> fck(H + W, 1), refck(H + W, 1);
	for (int i = 1; i < H + W; i++) {
		fck[i] = 1LL * fck[i - 1] * i % MOD;
	}
	refck[H + W - 1] = myPow(fck[H + W - 1], MOD - 2);
	for (int i = H + W - 1; i >= 1; i--) {
		refck[i - 1] = 1LL * refck[i] * i % MOD;
	}
	int n = 1;
	while (n <= H + W) n <<= 1;
	vector<vector<int> > f(4, vector<int>(n, 0)), g(4, vector<int>(n, 0));
	for (int i = 0; i < 4; i++) {
		int here = a[(i >> 1) ^ 1][1], there = a[i >> 1][(i & 1) << 1];
		for (int x = 0; x <= here && x <= there; x++) {
			f[i][x] = 1LL * fck[here] * fck[there] % MOD;
			f[i][x] = 1LL * f[i][x] * refck[here - x] % MOD;
			f[i][x] = 1LL * f[i][x] * refck[there - x] % MOD;
			f[i][x] = 1LL * f[i][x] * refck[x] % MOD;
			g[i][x] = f[i][x];
		}
		for (int x = here + 1; x <= there; x++) {
			g[i][x] = 1LL * fck[there] * refck[there - x] % MOD * refck[x - here] % MOD;
		}
	}
	vector<vector<int> > ff(2, vector<int>(n, 0)), gg(2, vector<int>(n, 0));
	for (int i = 0; i < 4; i += 2) {
		involve(f[i], f[i + 1], ff[i >> 1], n);
		involve(g[i], g[i + 1], gg[i >> 1], n);
	}
	int ans = 0;
	for (int i = min(a[0][0] + a[0][2], a[1][0] + a[1][2]); i >= 0; i--) {
		int u = a[0][0] + a[0][2] - i, v = a[1][0] + a[1][2] - i;
		int t = 1LL * ff[0][u] * gg[1][v] % MOD;
		t = (t + 1LL * gg[0][u] * ff[1][v]) % MOD;
		t = (t - 1LL * ff[0][u] * ff[1][v] % MOD + MOD) % MOD;
		t = 1LL * t * fck[i] % MOD;
		ans = (ans + t) % MOD;
	}
	cout << ans << "\n";
}

