const double eps=1e-12;
bool DP(double x,double y)
{
	if(x<0||y<0) return 0;
	if(x<y) swap(x,y); //x>y
	if(x>4*y) return 0;
	int c=0;
	for(int i=1;i<=n;i++) c+=a[i]/x+eps;
	if(c>=2*k) return 1;
	for(int i=0;i<=k;i++) f[i]=-1e9;
	f[0]=0;
	for(int i=1;i<=n;i++)
		for(int j=k;j>=0;j--)
			for(int c=0;c*x<=a[i]&&c<=j;c++)
				f[j]=max(f[j],(int)(f[j-c]+(a[i]-c*x)/y+eps));
	return f[k]>=k;
}
bool check(double S)
{
	int c=0;double x=sqrt(S);
	for(int i=1;i<=n;i++) c+=a[i]/x+eps;
	if(c>=2*k) return 1;
	for(int i=1;i<=n;i++)
		for(int p=0;p<=k;p++)
			for(int q=!p;q<=k;q++)
			{
				if(!p) 
				{
					double x=S*q/a[i];
					if(DP(x,S/x)) return 1;
				}
				else
				{
					double d=a[i]*a[i]-4*p*q*S;
					if(d>eps) 
					{
						double x=(a[i]+sqrt(d))/2/p;
						if(DP(x,S/x)) return 1;
						x=(a[i]-sqrt(d))/2/p;
						if(DP(x,S/x)) return 1;
					}
				}
			}
	return 0;
}
