// (1-z)^n
Poly bns(int n) {
  Poly ret(n + 1);
  for (int i = 0; i <= n; ++i) ret[i] = binom(n, i) * (i&1?-1:+1);
  return ret;
}

int N;
Int K;
int Q;
vector<int> D;

Poly ANS;

// C[i] z^A[i]/(1-z)^B[i]
vector<int> A, B;
vector<Mint> C;
Poly rec(int l, int r) {
  if (l + 1 == r) {
    return Poly{C[l]};
  } else {
    const int m = (l + r) / 2;
    const Poly resL = rec(l, m);
    const Poly resR = rec(m, r);
    return (resL << (A[m - 1] - A[r - 1])) + bns(B[l] - B[m]) * resR;
  }
}

void solve(int n, int di, int sig) {
  if (n < 0) return;
  A.clear();
  B.clear();
  C.clear();
  for (int i = 0; ; ++i) {
    const int a = n - 2*i;
    const int b = n - i + 1;
    if (a < 0 || b < 0) break;
    A.push_back(a);
    B.push_back(b);
    C.push_back(binom((i+1) + a - 1, a) * Mint(N - 1 - (di + i)).pow(K));
  }
  Poly fs = rec(0, (int)A.size());
if(N<=11)cerr<<"[solve] n = "<<n<<", di = "<<di<<", sig = "<<sig<<", A = "<<A<<", B = "<<B<<", C = "<<C<<": fs = "<<fs<<endl;
  ANS += sig * (fs << A.back()).div(bns(B[0]), N);
}

int main() {
  for (; ~scanf("%d%lld", &N, &K); ) {
    scanf("%d", &Q);
    D.resize(Q);
    for (int q = 0; q < Q; ++q) scanf("%d", &D[q]);
    
    ANS = Poly(N);
    solve(N - 2, 0, +1);
    solve(N - 4, 1, -1);
    // now allowing empty
if(N<=11)cerr<<"ANS = "<<ANS<<endl;
    
    for (int i = 0; i < N; ++i) ANS[i] *= invFac[i];
    Poly coef(N);
    for (int i = 0; i < N; ++i) coef[i] = invFac[i] * (i&1?-1:+1);
    ANS = (ANS * coef).mod(N);
    for (int i = 0; i < N; ++i) ANS[i] *= fac[i];
    
if(N<=11)cerr<<"ANS = "<<ANS<<endl;
    
    for (int q = 0; q < Q; ++q) {
      Mint ans = 0;
      if (N == 2) {
        ans += 1;
      } else {
        const int d = D[q];
        if (N - d >= 0) {
          ans += 2 * ANS[N - d]; 
        }
      }
      printf("%u\n", ans.x);
    }
  }
  return 0;
}
