#include<bits/stdc++.h>
using namespace std;
const int N=3e6+5,p=998244353;
int n,m,k,sm,ans,jc[N],inv[N];
inline int qpow(int x,int y){
	int re=1;
	while(y){
		if(y&1) re=1ll*re*x%p;
		x=1ll*x*x%p,y>>=1;
	}
	return re;
}
int main(){
