using INT = __int128;

struct RAT {
  INT p, q;
  RAT(INT p_ = 0, INT q_ = 1) : p(p_), q(q_) {
    if (q < 0) { p = -p; q = -q; }
  }
  void reduce() {
    const INT g = __gcd(p, q); p /= g; q /= g;
    if (q < 0) { p = -p; q = -q; }
  }
  RAT operator+(const RAT &a) const { return RAT(p * a.q + q * a.p, q * a.q); }
  RAT operator-(const RAT &a) const { return RAT(p * a.q - q * a.p, q * a.q); }
  RAT operator*(const RAT &a) const { return RAT(p * a.p, q * a.q); }
  RAT operator/(const RAT &a) const { return RAT(p * a.q, q * a.p); }
  RAT &operator+=(const RAT &a) { return *this = *this + a; }
  RAT &operator-=(const RAT &a) { return *this = *this - a; }
  RAT &operator*=(const RAT &a) { return *this = *this * a; }
  RAT &operator/=(const RAT &a) { return *this = *this / a; }
  RAT operator+() const { return *this; }
  RAT operator-() const { return RAT(-p, q); }
  bool operator< (const RAT &a) const { return ((__int128)p * a.q <  (__int128)q * a.p); }
  bool operator<=(const RAT &a) const { return ((__int128)p * a.q <= (__int128)q * a.p); }
  bool operator> (const RAT &a) const { return ((__int128)p * a.q >  (__int128)q * a.p); }
  bool operator>=(const RAT &a) const { return ((__int128)p * a.q >= (__int128)q * a.p); }
  bool operator==(const RAT &a) const { return ((__int128)p * a.q == (__int128)q * a.p); }
  bool operator!=(const RAT &a) const { return ((__int128)p * a.q != (__int128)q * a.p); }
  explicit operator double() const { return (double)p / (double)q; }
  explicit operator long double() const { return (long double)p / (long double)q; }
  explicit operator __float128() const { return (__float128)p / (__float128)q; }
  friend ostream &operator<<(ostream &os, const RAT &a) { os << a.p << "/" << a.q; return os; }
};


// floor(a / b)
template <class T> T divFloor(T a, T b) {
  return a / b - (((a ^ b) < 0 && a % b != 0) ? 1 : 0);
}

// ceil(a / b)
template <class T> T divCeil(T a, T b) {
  return a / b + (((a ^ b) > 0 && a % b != 0) ? 1 : 0);
}


// y^f(0) x y^(f(1)-f(0)) x y^(f(2)-f(1)) x ... x y^(f(n)-f(n-1))
//   where f(i) = floor((a i + b) / m)
// S: (unsigned or signed) integer
//   (a n + b) and (m + a) does not overflow
// T: monoid with pow
//   e: identity
template <class S, class T> T pathUnder(S m, S a, S b, S n, T e, T x, T y) {
  assert(m >= 1); assert(a >= 0); assert(b >= 0); assert(n >= 0);
  S c = (a * n + b) / m;
  T pre = e, suf = e;
  for (; ; ) {
    const S p = a / m; a %= m; x = x * y.pow(p);
    const S q = b / m; b %= m; pre = pre * y.pow(q);
    c -= (p * n + q);
    if (c == 0) return pre * x.pow(n) * suf;
    const S d = (m * c - b - 1) / a + 1;
    suf = y * x.pow(n - d) * suf;
    b = m - b - 1 + a; swap(m, a); n = c - 1; c = d; swap(x, y);
  }
}

