	else c.fl=1;
	if(!a.fl)c.qz=a.qz,c.qmn=a.qmn;
	else c.qz=a.qz+b.qz,c.qmn=min(a.qmn,b.qmn);
	if(!b.fl)c.hz=b.hz,c.hmn=b.hmn;
