inline void put(int o,int z){
	sm[o].mn+=z,sm[o].qmn+=z,sm[o].hmn+=z;lz[o]+=z;
}
inline void pushdown(int o){
	if(lz[o]){
		put(o<<1,lz[o]);put(o<<1|1,lz[o]);lz[o]=0;
	}
}
void su(int x,int o){
	sm[o].om=sm[o].am=0;
	if(b[x]||b[x+1])sm[o].fl=0;
	else sm[o].fl=1;
	if(b[x])sm[o].qz=0,sm[o].qmn=1e9;
	else sm[o].qz=1,sm[o].qmn=sm[o].mn;
	if(b[x+1])sm[o].hz=0,sm[o].hmn=1e9;
	else sm[o].hz=1,sm[o].hmn=sm[o].mn;
	if(b[x]&&b[x+1])sm[o].am=1;
}
void build(int l,int r,int o){
	lz[o]=0;
	if(l==r){
		sm[o].mn=0;su(l,o);return;
	}
	int mid=(l+r)>>1;
	build(l,mid,o<<1);build(mid+1,r,o<<1|1);
	sm[o]=sm[o<<1]+sm[o<<1|1];
}
void add(int l,int r,int o,int ll,int rr,int z){
	if(l>=ll&&r<=rr){
		put(o,z);return;
	}
	pushdown(o);
	int mid=(l+r)>>1;
	if(mid>=ll)add(l,mid,o<<1,ll,rr,z);
	if(mid<rr)add(mid+1,r,o<<1|1,ll,rr,z);
	sm[o]=sm[o<<1]+sm[o<<1|1];
}
