    if(W<=S1*2)return S1*24+(W-S1)*16;
    W=min(W-S1*2,S0*2);
    return W/2*28+(W&1)*12+S1*40;
}
ll calc(ll W,ll S){
    // cerr<<W<<' '<<S<<endl;
    ll l=(S+2)/3,r=min(W,S);
    if(l>r)return 0;
    // assert(l<=r);
    ll ans=0;
    #define check(m) (l<=(m)&&(m)<=r)&&(ans=max(ans,calc(W-(m),S-(m),m)))
    check(S/2);
    check(S/2+1);
    check(W/2);
    check(W/2+1);
    check(S+S-W);
    check(W/3);
    check(W/3+1);
    check(l);
    check(r);
    return ans+S*36;
    #undef check
}
ll solve(ll W,ll S){
    ll l=max(0ll,S-W*3),r=S;
    swap(l,r);
    l=S-l,r=S-r;
    // cerr<<l<<' '<<r<<endl;
    ll ans=0;
    auto check=[&](int m){
        for(int c=-2;c<=2;c++){
            int mm=m+c;
            if(l<=mm&&mm<=r){
                ans=max(ans,(S-(mm))*27+calc(W,(mm)));
            }
        }
    };
    check(W);
    check(W*2/3);
    check(W*2/3+1);
    check(W*3/4);
    check(W*3/4+1);
    for(int c:{0,1,2,3,4})check(c);
    for(int c:{0,1,2,3,4,5,6}){
        check((W*3-c-c)/2);
        check((W*3-c-c)/2+1);
        check((W*3+c)/5);
        check((W*3+c)/5+1);
        check(W-c);
        check(c*2);
        check(W*2);
        check(W*3/2-c);
        check(W*3/2-c+1);
        check(W*3-c);
    }
    check(W/2);
    check(W/2+1);
    check(W/3);
    check(W/3+1);
    check(l);
    check(r);
    #undef check
    return ans;
