inline void ntt(long long*f,int n,int type){
	for(int i=0,j=0;i<n;i++){
		if(i<j) swap(f[i],f[j]);
		for(int k=n>>1;(j^=k)<k;k>>=1);
	}
	for(int i=1;i<n;i<<=1){
