		else for(int j=i-2;j>=0;j-=2) w[j+1]=(__int128)w[j>>1]*tmp%mod,w[j]=w[j>>1];
		for(int j=0;j<n;j+=i<<1){
			for(int k=0;k<i;k++){
				tmp=(__int128)f[i+j+k]*w[k]%mod;
				f[i+j+k]=mo(f[j+k]-tmp+mod);
				f[j+k]=mo(f[j+k]+tmp);
			}
		}
	}
	if(type==-1){
		long long tmp=ksm(n);
		for(int i=0;i<n;i++) f[i]=(__int128)f[i]*tmp%mod;
	}
}
