			auto [y,id]=*it;
			mx[x0].erase(it);
			if(vis[id]) continue;
			vis[id]=true;
			pos.push_back(sum+abs(y-y0));
		}
	}else if(y0==y1){
		ll l=x0,r=x1;
		if(l>r) swap(l,r);
		while(1){
			auto it=my[y0].lower_bound({l,0});
			if(it==my[y0].end()||(*it)[0]>r) break;
			auto [x,id]=*it;
			my[y0].erase(it);
			if(vis[id]) continue;
			vis[id]=true;
			pos.push_back(sum+abs(x-x0));
		}
	}
	sum+=abs(x0-x1)+abs(y0-y1);
}
