  int n; cin >> n;
  vec a, b, c, d(n + 1, 0);
  a.push_back(1);
  F(i, 2, n) d[i] = query(1, i);
  F(i, 2, n) if (!d[i]) a.push_back(i);
  int u; F(i, 2, n) if (d[i]) { u = i; break; }
  b.push_back(u);
  F(i, 1, n) if (d[i] && u != i)
    if (!query(u, i)) b.push_back(i);
    else c.push_back(i);
  vec ans = solve(a, b, c);
  if (ans.front() > ans.back())
    reverse(ans.begin(), ans.end());
  cout << "! ";
  for (int x : ans) cout << x << " "; cout << endl;
}

