inline bool query(const vector<int> &s){
	if(s.size()<=1) return true;
	cout<<"? "<<s.size()<<' ';
	for(auto i:s){
		cout<<i<<' ';
	}
	cout<<endl;
	int res;
	cin>>res;
	return res;
}
inline void solve(vector<int> s){
	if(s.empty()) return;
	vector<int> t1,t2;
	for(auto i:s){
		t1.push_back(i);
		if(!query(t1)){
			t1.pop_back();
			t2.push_back(i);
		}
	}
	for(auto i:t2){
		vector<int> t3=t1;
		while(true){
			if(t3.size()!=t1.size()){
				t3.push_back(i);
				if(query(t3)) break;
				t3.pop_back();
			}
			int L=1,R=t3.size();
			while(L<R){
				int M=(L+R)/2;
				vector<int> v1;
				for(int i=L;i<=M;i++){
					v1.push_back(t3[i-1]);
				}
				v1.push_back(i);
				if(!query(v1)){
					R=M;
				} else{
					L=M+1;
				}
			}
			ans.push_back({i,t3[L-1]});
			vector<int> t4;
			for(auto i:t3){
				if(i!=t3[L-1]){
					t4.push_back(i);
				}
			}
			t3=t4;
		}
	}
	solve(t2);
}
