#include <bits/stdc++.h>

using namespace std;

const int N = 5e5 + 5;
int n, m, q, c, op[N], qx[N], qy[N];
int tx[N], ty[N], ansx[N], ansy[N];

struct BIT {
	int n, c[N];
	inline void init(int sz) {
		n = sz;
	}
	inline void add(int x, int v) {
		for (; x <= n; x += x & -x) c[x] += v;
	}
	inline int kth(int k) {
		int x = 0;
		for (int i = __lg(n); i >= 0; --i) {
			if (x + (1 << i) <= n && c[x + (1 << i)] < k) {
				k -= c[x + (1 << i)];
				x += 1 << i;
			}
		}
		return x + 1;
	}
} R, C;

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0);
	cin >> q >> c;
	n = m = 1;
	for (int i = 1; i <= q; ++i) {
		cin >> op[i] >> qx[i] >> qy[i];
		if (op[i] == 1) ++n;
		else if (op[i] == 2) ++m;
	}
	R.init(n), C.init(m);
	for (int i = 1; i <= n; ++i) R.add(i, 1);
	for (int i = 1; i <= m; ++i) C.add(i, 1);
	for (int i = q; i >= 1; --i) {
		int cur = 0;
		if (op[i] == 1) {
			cur = R.kth(qx[i] + 1);
			tx[cur] = i;
			R.add(cur, -1);
		} else if (op[i] == 2) {
			cur = C.kth(qx[i] + 1);
			ty[cur] = i;
			C.add(cur, -1);
		} else {
			ansx[i] = R.kth(qx[i]);
			ansy[i] = C.kth(qy[i]);
		}
	}
	qy[0] = c;
	for (int i = 1; i <= q; ++i)
		if (op[i] == 3) {
			if (tx[ansx[i]] >= ty[ansy[i]])
				cout << qy[tx[ansx[i]]] << '\n';
			else
				cout << qy[ty[ansy[i]]] << '\n';
		}
	return 0;
}

