LL fs(LL a,LL b,LL c,LL n) { //i=0~n[ai+b/c]
	if(!a) return (b/c)*(n+1);
	if(a>=c||b>=c) return fs(a%c,b%c,c,n)+(a/c)*n*(n+1)/2+(b/c)*(n+1);
	return (a*n+b)/c*(n+1)-fs(c,c-b+a-1,a,(a*n+b)/c-1);
}
