struct point { ll x, y; };
inline double slope(point A, point B) {
  return 1. * (A.y - B.y) / (A.x - B.x);
}
ll mx[N];
inline void divide(int l, int r) {
  if (l == r)
    return mx[1] = std::max(mx[1], (ll)a[l]), void();
  int mid = l + r >> 1;
  divide(l, mid), divide(mid + 1, r);
  static point cl[N], cr[N]; int nl = 0, nr = 0;
  ll cnt = 0, sum = 0;
  for (int i = mid; i >= l; i--) {
    point x = {++cnt, sum += a[i]};
    while (nl >= 2 && slope(cl[nl - 1], x) <= slope(cl[nl], x))
      nl--;
    cl[++nl] = x;
  }
  cnt = sum = 0;
  for (int i = mid + 1; i <= r; i++) {
    point x = {++cnt, sum += a[i]};
    while (nr >= 2 && slope(cr[nr - 1], x) <= slope(cr[nr], x))
      nr--;
    cr[++nr] = x;
  }
  for (int i = 1, j = 1; ; ) {
    mx[cl[i].x + cr[j].x] = std::max(mx[cl[i].x + cr[j].x], cl[i].y + cr[j].y);
    if (i == nl && j == nr) break;
    if (j == nr || (i < nl && slope(cl[i], cl[i + 1]) >= slope(cr[j], cr[j + 1])))
      i++;
    else
      j++;
  }
}
point c[N]; int m;
inline void solve(int tt) {
