  m = 0;
  for (int i = 1; i <= n; i++) {
    point x = {i, mx[i]};
    while (m >= 2 && slope(c[m - 1], x) <= slope(c[m], x))
      m--;
    c[++m] = x;
  }
  while (q--) {
    ll x;
    scanf("%lld", &x), x = -x;
    int l = 2, r = m, p = 1;
    while (l <= r) {
      int mid = l + r >> 1;
      if (slope(c[mid - 1], c[mid]) >= x)
        p = mid, l = mid + 1;
      else
        r = mid - 1;
    }
    printf("%lld ", c[p].y - c[p].x * x);
  }
  puts("");
}
