#include <bits/stdc++.h>
constexpr int N = 1e5 + 10;
int n;
std::vector<std::pair<int, int>> edge[N], e0;
int m, dfn[N], rdfn[N], vis[N];
std::vector<int> col[N];
void dfs1(int u, int fa) {
  dfn[u] = ++m;
  for (auto [v, w] : edge[u]) {
    if (v == fa) continue;
    if (! vis[w]++)
      col[w].push_back(v);
    dfs1(v, u);
    vis[w]--;
  }
  rdfn[u] = m;
}
int mx[N * 4], tag[N * 4];
inline void build(int k = 1, int l = 1, int r = m) {
  mx[k] = tag[k] = 0;
  if (l != r) {
    int mid = l + r >> 1;
    build(k << 1, l, mid);
    build(k << 1 | 1, mid + 1, r);
  }
}
inline void modify(int x, int y, int z, int k = 1, int l = 1, int r = m) {
  if (x <= l && r <= y)
    return mx[k] += z, tag[k] += z, void();
  int mid = l + r >> 1;
  if (x <= mid)
    modify(x, y, z, k << 1, l, mid);
  if (mid < y)
    modify(x, y, z, k << 1 | 1, mid + 1, r);
  mx[k] = std::max(mx[k << 1], mx[k << 1 | 1]) + tag[k];
}
inline bool dfs2(int u, int fa, int U) {
  bool res = mx[1] == U;
  for (auto [v, w] : edge[u]) {
    if (v == fa) continue;
    if (w <= U && ! vis[w]++) {
      for (int uw : col[w])
        modify(dfn[uw], rdfn[uw], -1);
      modify(1, m, +1);
    }
    res |= dfs2(v, u, U);
    if (w <= U && ! --vis[w]) {
      modify(1, m, -1);
      for (int uw : col[w])
        modify(dfn[uw], rdfn[uw], +1);
    }
  }
  return res;
}
inline bool check(int rt1, int rt2, int U) {
  build();
  for (int w = 1; w <= U; w++)
    for (int u : col[w])
      modify(dfn[u], rdfn[u], +1);
  return dfs2(rt2, rt1, U);
}
inline int calc(int rt1, int rt2) {
  m = 0, vis[0] = 1;
  for (int i = 1; i <= n; i++)
    col[i].clear();
  dfs1(rt1, rt2);
  int l = 1, r = n - 1, ans = 0;
  while (l <= r) {
    int mid = l + r >> 1;
    if (check(rt1, rt2, mid))
      ans = mid, l = mid + 1;
    else
      r = mid - 1;
  }
  return ans;
}
inline void solve(int tt) {
  scanf("%d", &n);
  for (int i = 1; i <= n; i++)
    edge[i].clear();
  e0.clear();
  for (int i = 1; i < n; i++) {
    int u, v, w;
    scanf("%d%d%d", &u, &v, &w);
    edge[u].emplace_back(v, w);
    edge[v].emplace_back(u, w);
    if (w == 0)
      e0.emplace_back(u, v);
  }
  int ans = -1;
  for (auto [u, v] : e0)
    ans = std::max(ans, calc(u, v));
  printf("%d\n", ans + 1);
}
int main() {
  int t;
  scanf("%d", &t);
  for (int tt = 1; tt <= t; tt++)
    solve(tt);
  return 0;
}

