struct DSU{
	int fa[N],cnt;
	pii sta[N];int top;
	void init(int n){
		top=0;cnt=n;
		memset(fa,-1,sizeof(int)*(n+5));
	}
	int find(int x){
		if(fa[x]<0)return x;
		return find(fa[x]);
	}
	void merge(int x,int y){
		x=find(x),y=find(y);
		if(fa[x]>fa[y])swap(x,y);
		if(x^y){
			--cnt;
			sta[++top]=mp(y,fa[y]);
			fa[x]+=fa[y];fa[y]=x;
		}
	}
	void undo(int lim){
		while(top>lim){
			int y=sta[top].fi,z=sta[top].se;
			int x=fa[y];
			fa[y]=z;fa[x]-=fa[y];
			--top;++cnt;
		}
	}
} D;
int ans[N];
struct SGT{
	#define ls (rt<<1)
	#define rs (rt<<1|1)
	basic_string<pii> tr[N<<2];
	void upd(int rt,int l,int r,int ul,int ur,pii v){
//		if(ul<=ur)cout<<v.fi<<" "<<v.se<<"\n";
		if(ul>r||ur<l)return;
		else if(ul<=l&&ur>=r)tr[rt]+=v;
		else{
			int mid=l+r>>1;
			upd(ls,l,mid,ul,ur,v);
			upd(rs,mid+1,r,ul,ur,v);
		}
	}
	void solve(int rt,int l,int r){
		int tmp=D.top;
		for(pii t:tr[rt])D.merge(t.fi,t.se);
		tr[rt].clear();
		if(l==r)ans[l]=D.cnt;
		else{
			int mid=l+r>>1;
			solve(ls,l,mid);
			solve(rs,mid+1,r);
		}
		D.undo(tmp);
	}
	#undef ls
	#undef rs
} T;
