	lsf[x]=now;
}
void updg(int x){
	if(x<0||x>n)return;
	int tmp=g[x];g[x]=n+1;
	for(int i=0;i<20;i++){
		if(a[x]>>i&1)g[x]=min(g[x],nxt[x][i]);
	}
	if(tmp==g[x])return;
	if(tmp<=n&&R[x])T.upd(1,0,q,lsg[x],now-1,mp(tmp,x));
	lsg[x]=now;
}
void upda(int x,int y){
	basic_string<int> todo;
	for(int i=0;i<20;i++){
		if(!((a[x]^y)>>i&1))continue;
		if(a[x]>>i&1){
			st[i].erase(x);
			int u=pre[x][i],v=nxt[x][i];
			pre[x][i]=nxt[x][i]=0;
			nxt[u][i]=v;pre[v][i]=u;
			todo+=u;todo+=v;
		}
		else{
			auto it=st[i].insert(x).fi;
			--it;int u=*it;
			++it;++it;int v=*it;
			nxt[u][i]=x;pre[v][i]=x;
			pre[x][i]=u;nxt[x][i]=v;
			todo+=u;todo+=v;
		}
	}
	todo+=x;a[x]=y;
	for(int t:todo){
		updf(t);updg(t);
	}
}
void updl(int x,int y){
	if(L[x]==y)return;
	if(f[x]>=1&&L[x]){
		T.upd(1,0,q,lsf[x],now-1,mp(f[x],x));
	}
	L[x]=y;lsf[x]=now;
}
void updr(int x,int y){
	if(R[x]==y)return;
	if(g[x]<=n&&R[x]){
		T.upd(1,0,q,lsg[x],now-1,mp(x,g[x]));
	}
	R[x]=y;lsg[x]=now;
}
void solve(){
