#include <bits/stdc++.h>
using namespace std;
using db = double;
const db inf = 1e18;
struct Line {
	mutable db k, m, p;
	bool operator<(const Line& o) const { return k < o.k; }
	bool operator<(db x) const { return p < x; }
};
struct LineContainer : multiset<Line, less<>> {
	// (for doubles, use inf = 1/.0, div(a,b) = a/b)
	db div(db a, db b) { // floored division
		return a / b; }
	bool isect(iterator x, iterator y) {
		if (y == end()) return x->p = inf, 0;
		if (x->k == y->k) x->p = x->m > y->m ? inf : -inf;
		else x->p = div(y->m - x->m, x->k - y->k);
		return x->p >= y->p;
	}
	void add(db k, db m) {
		auto z = insert({k, m, 0}), y = z++, x = y;
		while (isect(y, z)) z = erase(z);
		if (x != begin() && isect(--x, y)) isect(x, y = erase(y));
		while ((y = x) != begin() && (--x)->p >= y->p)
			isect(x, erase(y));
	}
	db query(db x) {
		assert(!empty());
		auto l = *lower_bound(x);
		return l.k * x + l.m;
	}
} f[10];
int N, M;
void solve() {
	cin >> N >> M;
	for (int i = 1; i <= M; i++) {
		f[i].clear();
	};
	db A = 0, B = 0;
	for (int z = 1; z <= N; z++) {
		int s, g, t; cin >> s >> g >> t;
		f[t].add(s, -1LL * s * g);
		A += 1LL * s * g, B += s;
		if (z < 2 * M) {
			continue;
		}
		db lo = 0, hi = 1e10;
		while ((hi - lo) / hi > 1e-6) {
			db mid = (lo + hi) / 2, sum = A - B * mid;
			for (int i = 1; i <= M; i++) {
				db v = f[i].query(mid);
				sum += max(0., v);
			}
			if (sum >= 0) lo = mid;
			else hi = mid;
		}
		cout << lo << '\n';
	}
}
int main() {
	ios::sync_with_stdio(false), cin.tie(nullptr);
	cout.precision(10), cout << fixed;
	int T; cin >> T;
	while (T--) solve();
	return 0;
}

#include <bits/stdc++.h>
// https://www.cnblogs.com/caijianhong/p/18017272/template-poly
typedef long long LL;
template <unsigned umod>
struct modint {
  static constexpr int mod = umod;
  unsigned v;
  modint() : v(0) {}
  template <class T, std::enable_if_t<std::is_integral<T>::value>* = nullptr>
  modint(T x) {
    x %= mod;
    if (x < 0) x += mod;
    v = x;
  }
  modint(const std::string& str) {
    v = 0;
    size_t i = 0;
    if (str.front() == '-') i += 1;
    while (i < str.size()) {
      assert(isdigit(str[i]));
      v = (v * 10ull % umod + str[i] - '0') % umod;
      i += 1;
    }
    if (str.front() == '-' && v) v = umod - v;
  }
  modint operator+() const { return *this; }
  modint operator-() const { return modint() - *this; }
  friend int raw(const modint& self) { return self.v; }
  friend std::istream& operator>>(std::istream& is, modint& self) {
    std::string str;
    is >> str;
    self = str;
    return is;
  }
  friend std::ostream& operator<<(std::ostream& os, const modint& self) {
    return os << raw(self);
  }
  modint& operator+=(const modint& rhs) {
    v += rhs.v;
    if (v >= umod) v -= umod;
    return *this;
  }
  modint& operator-=(const modint& rhs) {
    v -= rhs.v;
    if (v >= umod) v += umod;
    return *this;
  }
  modint& operator*=(const modint& rhs) {
    v = static_cast<unsigned>(1ull * v * rhs.v % umod);
    return *this;
  }
  modint& operator/=(const modint& rhs) {
    static constexpr size_t ilim = 1 << 20;
    static modint inv[ilim + 10];
    static int sz = 0;
    assert(rhs.v);
    if (rhs.v > ilim) return *this *= qpow(rhs, mod - 2);
    if (!sz) inv[1] = sz = 1;
    while (sz < (int)rhs.v) {
      for (int i = sz + 1; i <= sz << 1; i++) inv[i] = -mod / i * inv[mod % i];
      sz <<= 1;
    }
    return *this *= inv[rhs.v];
  }
  template <class T>
  friend modint qpow(modint a, T b) {
    modint r = 1;
    for (; b; b >>= 1, a *= a)
      if (b & 1) r *= a;
    return r;
  }
  friend modint operator+(modint lhs, const modint& rhs) { return lhs += rhs; }
  friend modint operator-(modint lhs, const modint& rhs) { return lhs -= rhs; }
  friend modint operator*(modint lhs, const modint& rhs) { return lhs *= rhs; }
  friend modint operator/(modint lhs, const modint& rhs) { return lhs /= rhs; }
  friend bool operator==(const modint& lhs, const modint& rhs) {
    return lhs.v == rhs.v;
  }
  friend bool operator!=(const modint& lhs, const modint& rhs) {
    return lhs.v != rhs.v;
  }
};
typedef modint<998244353> mint;
int glim(const int& x) { return 1 << (32 - __builtin_clz(x - 1)); }
int bitctz(const int& x) { return __builtin_ctz(x); }
