const int invG=qpow(G,M-2);
void NTT(int *f,int flag,int n){
	for(int i=0;i<n;i++){
		if(i<tr[i]) swap(f[i],f[tr[i]]);
	}
	for(int p=2;p<=n;p<<=1){
		int len=p>>1;
		int tG=qpow(flag?invG:G,(M-1)/p);
		for(int k=0;k<n;k+=p){
			int buf=1;
			for(int l=k;l<k+len;l++){
				int t=1LL*f[l+len]*buf%M;
				f[l+len]=(f[l]-t+M)%M;
				add(f[l],t);
				buf=1LL*buf*tG%M;
			}
		}
	}
	return;
}
vector<int> MUL(vector<int> f,vector<int> g){
	int n=(int)f.size()-1,m=(int)g.size()-1;
	static int X1[N<<1],Y1[N<<1];
	for(int i=0;i<=(n+m)*2;i++) X1[i]=Y1[i]=tr[i]=0;
	for(int i=0;i<=n;i++) X1[i]=f[i];
	for(int i=0;i<=m;i++) Y1[i]=g[i];
	for(m+=n,n=1;n<m+1;n<<=1);
	for(int i=0;i<n;i++){
		tr[i]=tr[i>>1]>>1|((i&1)?(n>>1):0);
	}
	NTT(X1,0,n),NTT(Y1,0,n);
	for(int i=0;i<n;i++) X1[i]=1LL*X1[i]*Y1[i]%M;
	NTT(X1,1,n);
	int invn=qpow(n,M-2);
	for(int i=0;i<=m;i++) X1[i]=1LL*X1[i]*invn%M;
	vector<int> ans(m+1);
	for(int i=0;i<=m;i++) ans[i]=X1[i];
	return ans;
}
