		if(a[1]==0)puts("2");
		else puts("1");
		return;
	}
	mp.clear();
	for(int i=1;i<=n;i++)mp[a[i]]++;
	int val=1,p=k-1,ans=1;
	for(;p>=0;p--){
		if(val>n)break;
