  mn[u] = str[u] == '0' ? (k + 1) : 0;
  for (int v : G[u]) {
    G[v].erase(std::find(G[v].begin(), G[v].end(), u));
    dfs1(v);
    mn[u] = std::min(mn[u], mn[v] + 1);
  }
}
int ans[N];
void dfs2(int u, int x) {
  if (x == -1)
    x = k - 1, ans[u]++;
  if (x >= mn[u])
    x = std::max(x, k - mn[u]);
  for (int v : G[u])
    ans[v] = ans[u], dfs2(v, x - 1);
}
