#define poly vector<int>
#define N 21
void output(poly a){
	for(auto cu:a)printf("%d ",cu);
	printf("\n");
}
poly mul(int k,poly a){
	int sz=a.size();
	poly b;
	for(int i=0;i<sz;++i)b.emplace_back(1ll*k*a[i]%mod);
	return b;
}
poly plu(poly a,poly b){
	poly c;
	int s1=a.size(),s2=b.size();
	c.resize(max(s1,s2));
	for(int i=0;i<s1;++i)c[i]=(c[i]+a[i])%mod;
	for(int i=0;i<s2;++i)c[i]=(c[i]+b[i])%mod;
	return c;
}
poly mns(poly a,poly b){
	poly c;
	int s1=a.size(),s2=b.size();
	c.resize(max(s1,s2));
	for(int i=0;i<s1;++i)c[i]=(c[i]+a[i])%mod;
	for(int i=0;i<s2;++i)c[i]=(c[i]-b[i]+mod)%mod;
	return c;
}
int a[1<<N],b[1<<N],ap[1<<N],bp[1<<N];
int rev[1<<N];
void getrev(int l){
	rev[0]=0;
	for(int i=1;i<=l;++i){
		for(int j=0;j<(1<<(i-1));++j){
			rev[j^(1<<(i-1))]=rev[j]^(1<<(l-i));
		}
	}
}
int cj[1<<N];
void ntt(int l,int *c,int *d,int cd){
	for(int i=0;i<(1<<l);++i)d[i]=c[rev[i]];
	for(int i=1;i<(1<<l);i<<=1){
		int o1=powdv(3,(mod-1)/i/2);cj[0]=1;
		if(cd==-1)o1=powdv(o1);
		for(int k=1;k<i;++k)cj[k]=1ll*cj[k-1]*o1%mod;
		for(int j=0;j<(1<<l);j+=i+i){
			for(int k=0;k<i;++k){
				int A=d[j+k],B=1ll*cj[k]*d[j+k+i]%mod;
				d[j+k]=A+(B>=mod-A?B-mod:B);d[j+k+i]=A+(B>A?mod-B:-B);
			}
		}
	}
	if(cd==-1){
		int ny=powdv(1<<l);
		for(int i=0;i<(1<<l);++i)d[i]=1ll*d[i]*ny%mod;
	}
}
poly multi(vector<poly>g){
	int sz=0;
	for(auto p:g)sz+=p.size()-1;
	int ss=sz+1;
	while(ss&(ss-1))++ss;
	int l=__builtin_ctz(ss);
	getrev(l);
	for(int i=0;i<(1<<l);++i)ap[i]=1;
	for(auto p:g){
		int zz=p.size();
		for(int i=0;i<(1<<l);++i){
			a[i]=(i<zz?p[i]:0);
		}
		ntt(l,a,bp,1);
		for(int i=0;i<(1<<l);++i)ap[i]=1ll*ap[i]*bp[i]%mod;
	}
	ntt(l,ap,b,-1);
	poly ans;
	for(int i=0;i<=sz;++i)ans.emplace_back((b[i]+mod)%mod);
	return ans;
}
poly inv(poly x,int n){
	int m=x.size();
	poly y(n);y[0]=1;
	for(int k=1;;++k){
		getrev(k+1);
		int d=k+1;
		for(int i=0;i<(1<<d);++i){
			a[i]=(i<(1<<k)&&i<m?x[i]:0);
			b[i]=(i<(1<<(k-1))?y[i]:0);
		}
		ntt(d,a,ap,1);ntt(d,b,bp,1);
		for(int i=0;i<(1<<d);++i){
			bp[i]=(2*bp[i]+1ll*bp[i]*bp[i]%mod*(mod-ap[i]))%mod;
		}
		ntt(d,bp,b,-1);
		for(int i=0;i<(1<<k)&&i<n;++i){
			y[i]=b[i];
			if(y[i]<0)y[i]+=mod;
		}
		if((1<<k)>=n)break;
	}
	return y;
}
int id[1<<N],di[1<<N],ny[1<<N];
void init(int sz){
	di[0]=1;
	for(int i=1;i<=sz;++i)di[i]=1ll*i*di[i-1]%mod;
	id[sz]=powdv(di[sz]);
	for(int i=sz-1;i>=0;--i)id[i]=1ll*id[i+1]*(i+1)%mod;
	for(int i=1;i<=sz;++i)ny[i]=1ll*id[i]*di[i-1]%mod;
}
poly up(int n){
	if(n==0)return {1};
	if(n&1)return multi({up(n-1),{n-1,1}});
	int nn=n/2;
	poly a=up(nn);
	poly a1,a2;
	for(int i=0;i<=nn;++i)
		a1.emplace_back(1ll*di[i]*a[i]%mod);
	int cj=powdv(nn,nn),cc=powdv(nn);
	for(int i=0;i<=nn;++i)
		a2.emplace_back(1ll*cj*id[nn-i]%mod),cj=1ll*cj*cc%mod;
	poly c=multi({a1,a2}),cp;
	for(int i=nn;i<=nn+nn;++i)cp.emplace_back(1ll*c[i]*id[i-nn]%mod);
	return multi({a,cp});
}
poly dn(int n){
	poly pp=up(n);
	for(int i=0;i<=n;++i)if((n-i)%2)pp[i]=(mod-pp[i])%mod;
	return pp;
}
int C(int n,int m){
	if(n<0||m<0||n<m)return 0;
	return 1ll*di[n]*id[m]%mod*id[n-m]%mod;
}
