#include <bits/stdc++.h>
using namespace std;

using ui = unsigned;
using ll = long long;
using ull = unsigned long long;
using ld = long double;
#define rep(i,l,r) for(int i=(l);i<=(r);++i)
#define per(i,l,r) for(int i=(l);i>=(r);--i)
#define repn(i,n) for(int i=0;i<(n);++i)
#define sizc(x) ((int)(x).size())
#define allc(x) (x).begin(),(x).end()
#define fir first
#define sec second

constexpr int N=3e5+5;

int n;
ll k;
pair<ll,ll> a[N];
ll s1[N],s2[N];

ll tri(ll n){
	return n*(n+1)/2;
}

void solve(){
	cin>>n>>k;
	rep(i,1,n)cin>>a[i].sec;
	rep(i,1,n)cin>>a[i].fir;
	sort(a+1,a+n+1);
	int m=1;ll p=a[1].fir+a[1].sec;
	ll sum=tri(a[1].sec);rep(i,2,n){
		if(a[i].fir>p){
			sum+=tri(a[i].sec);
			a[++m]=a[i];
			p=a[i].fir+a[i].sec;
			continue;
		}
		sum+=tri(a[i].sec)+a[i].sec*(p-a[i].fir);
		p+=a[i].sec,a[m].sec+=a[i].sec;
	}
	n=m;
	ll ans=0;
	rep(i,2,n){
		ll pl=a[i-1].fir+a[i-1].sec,d=a[i].fir-pl;
		s1[i]=s1[i-1]+d;
		s2[i]=s2[i-1]+pl*d+tri(d);
	}
	int pt=1;
	rep(i,1,n){
		pt=max(pt,i);while(pt<n&&s1[pt+1]-s1[i]<=k)++pt;
		ll sum=s2[pt]-s2[i];
		ll lk=k-(s1[pt]-s1[i]);
		sum+=lk*(a[pt].fir+a[pt].sec)+tri(lk);
		ans=max(ans,sum-k*a[i].fir);
	}
	cout<<ans+sum<<'\n';
}

signed main(){
	ios::sync_with_stdio(false);
	cin.tie(nullptr);

	int T;cin>>T;
	while(T--)solve();
}

