#include <bits/stdc++.h>
using u128 = __uint128_t;
using ull = unsigned long long;
constexpr ull P = 998244353, mod = 458799232334658703;
constexpr int N = 1e6 + 10;
int n, len[N];
std::string s[N];
std::vector<ull> pre[N], suf[N];
ull ans = 0;
std::unordered_map<ull, int> mp1, mp2;
int son[N][26], fail[N], cnt[N], tot;
int main() {
  std::ios::sync_with_stdio(false), std::cin.tie(nullptr);
  std::cin >> n;
  for (int i = 0; i < n; i++) {
    std::cin >> s[i], len[i] = s[i].size(), s[i] = " " + s[i];
    pre[i].resize(len[i] + 1), suf[i].resize(len[i] + 1);
    pre[i][0] = suf[i][0] = 0;
    ull pw = 1;
    for (int j = 1; j <= len[i]; j++) {
      pre[i][j] = (pre[i][j - 1] + (u128)pw * s[i][j]) % mod;
      suf[i][j] = (s[i][len[i] + 1 - j] + (u128)P * suf[i][j - 1]) % mod;
      pw = (u128)pw * P % mod;
    }
    for (int j = 1; j <= len[i]; j++)
      ans += mp1[suf[i][j]];
    for (int j = 1; j <= len[i]; j++)
      if (pre[i][j] == suf[i][j])
        ans += mp2[pre[i][len[i] - j]];
    for (int j = 1; j <= len[i]; j++)
      mp1[pre[i][j]]++;
    for (int j = 1; j <= len[i]; j++)
      if (pre[i][j] == suf[i][j])
        mp2[suf[i][len[i] - j]]++;
    int u = 0;
    for (int j = 1; j <= len[i]; j++) {
      int &v = son[u][s[i][j] - 'a'];
      u = v = ! v ? ++tot : v;
    }
    cnt[u]++;
  }
  std::queue<int> Q;
  for (int c = 0; c < 26; c++)
    if (son[0][c])
      Q.push(son[0][c]);
  while (! Q.empty()) {
    int u = Q.front(); Q.pop();
    cnt[u] += cnt[fail[u]];
    for (int c = 0; c < 26; c++) {
      int &v = son[u][c];
      if (! v) v = son[fail[u]][c];
      else fail[v] = son[fail[u]][c], Q.push(v);
    }
  }
  for (int i = 1; i <= n; i++) {
    int u = 0;
    for (int j = 1; j < len[i]; j++) {
      u = son[u][s[i][j] - 'a'];
      if (pre[i][len[i] - j] == suf[i][len[i] - j])
        ans += cnt[u];
    }
  }
  printf("%llu\n", ans);
  return 0;
}

#include <bits/stdc++.h>
int N,dp[1000009],a[1000009],iv[500009],p[500009],ll[500009],rr[500009],sg[500009];
#define lb(x) ((x)&(-(x)))
void up(int n,int v) {
    while(n<=N) {
        sg[n]=std::max(sg[n],v);
        n+=lb(n);
    }
}
int qr(int n) {
    int as=0;
    while(n) {
        as=std::max(as,sg[n]);
        n-=lb(n);
    }
    return as;
}
bool cmp(int x,int y) {
    if(ll[x]/10000==ll[y]/10000) return rr[x]<rr[y];
    return ll[x]<ll[y];
}
signed main(void) {
    scanf("%d",&N);
    for(int i=1;i<=2*N;i++) {
